int CCanvasWnd::Scale(int value) const
{
    const UINT dpi = (GetSafeHwnd() != nullptr) ? ::GetDpiForWindow(GetSafeHwnd()) : USER_DEFAULT_SCREEN_DPI;
    return ::MulDiv(value, static_cast<int>(dpi), USER_DEFAULT_SCREEN_DPI);
