        {
            CancelStroke();
        }
        return;
    }
    BeginStroke(point, MouseButton::Left);
}

void CCanvasWnd::OnLButtonUp(UINT nFlags, CPoint point)
{
    if (m_stroking && m_strokeButton == MouseButton::Left)
    {
        EndStroke(point, nFlags);
    }
}

void CCanvasWnd::OnRButtonDown(UINT, CPoint point)
{
    if (m_stroking)
    {
        if (m_strokeButton != MouseButton::Right)
        {
            CancelStroke();
        }
        return;
    }
    BeginStroke(point, MouseButton::Right);
}

void CCanvasWnd::OnRButtonUp(UINT nFlags, CPoint point)
{
    // 기본 처리를 하지 않아 WM_CONTEXTMENU가 생기지 않게 함
    if (m_stroking && m_strokeButton == MouseButton::Right)
    {
        EndStroke(point, nFlags);
    }
}

void CCanvasWnd::OnMouseMove(UINT nFlags, CPoint point)
{
    if (!m_trackingMouse)
    {
        TRACKMOUSEEVENT tme{};
        tme.cbSize = sizeof(tme);
        tme.dwFlags = TME_LEAVE;
        tme.hwndTrack = GetSafeHwnd();
        m_trackingMouse = ::TrackMouseEvent(&tme) != FALSE;
    }

    const CPoint pt = ClientToImage(point);
    const bool inside = m_surface.Contains(pt);
    NotifyCursor(pt, inside);
    UpdateHover(point, inside);

    if (m_stroking)
    {
        ApplyCursor(inside); // 캡처 중에는 WM_SETCURSOR가 오지 않음
        m_lastImagePt = pt;
        CurrentTool().Drag(*this, pt, (nFlags & MK_SHIFT) != 0);
    }
}

void CCanvasWnd::OnMouseLeave()
{
    m_trackingMouse = false;
    NotifyCursor(CPoint(0, 0), false);
    UpdateHover(CPoint(0, 0), false);
}

void CCanvasWnd::OnCaptureChanged(CWnd* pWnd)
{
    // 다른 창이 캡처를 가져가면(예: Alt+Tab) 마지막 위치에서 그리기를 마무리
    if (m_stroking && pWnd != this)
    {
        m_stroking = false;
        CurrentTool().End(*this, m_lastImagePt, false);
    }
    CWnd::OnCaptureChanged(pWnd);
}

BOOL CCanvasWnd::OnSetCursor(CWnd* pWnd, UINT nHitTest, UINT message)
{
    if (nHitTest == HTCLIENT)
    {
        CPoint pt;
        ::GetCursorPos(&pt);
        ScreenToClient(&pt);
        ApplyCursor(m_surface.Contains(ClientToImage(pt)));
        return TRUE;
    }
    return CWnd::OnSetCursor(pWnd, nHitTest, message);
}

void CCanvasWnd::ApplyCursor(bool insideImage)
{
    if (!insideImage)
    {
        ::SetCursor(::LoadCursor(nullptr, IDC_ARROW));
    }
    else if (CurrentTool().HasCustomCursor())
    {
        ::SetCursor(nullptr); // 도구가 직접 그린 커서만 보이게
    }
    else
    {
        ::SetCursor(::LoadCursor(nullptr, IDC_CROSS));
    }
}

void CCanvasWnd::UpdateHover(CPoint ptClient, bool inside)
{
    const bool visible = inside && CurrentTool().HasCustomCursor();
    const CPoint pt = ClientToImage(ptClient);
    if (visible == m_hoverVisible && (!visible || pt == m_hoverImagePt))
    {
        return;
    }
    if (m_hoverVisible)
    {
        InvalidateRect(HoverClientRect(), FALSE);
    }
    m_hoverVisible = visible;
    m_hoverImagePt = pt;
    if (m_hoverVisible)
    {
        InvalidateRect(HoverClientRect(), FALSE);
    }
}

CRect CCanvasWnd::HoverClientRect() const
{
    const int size = GetToolSize(m_tool);
    CRect rc(m_hoverImagePt.x - size / 2, m_hoverImagePt.y - size / 2,
             m_hoverImagePt.x - size / 2 + size, m_hoverImagePt.y - size / 2 + size);
    rc.InflateRect(2, 2);
    return ImageToClient(rc);
}

void CCanvasWnd::NotifyCursor(CPoint ptImage, bool inside)
{
    GetParent()->SendMessage(WM_CANVAS_CURSOR, inside ? 1 : 0, MAKELPARAM(ptImage.x, ptImage.y));
}

#pragma once

/**
 * @file ColorPalette.h
 * @brief 색 1/색 2 표시와 기본 색 상자
 */

#include <array>

/**
 * @brief 색 팔레트 컨트롤.
 *
 * 왼쪽에 색 1(앞)과 색 2(뒤)를 겹쳐 보여 주고, 오른쪽에 2줄 × 14칸의 기본 색을 보여 줍니다.
 * - 색 칸을 왼쪽 클릭: 색 1, 오른쪽 클릭: 색 2로 정함
 * - 색 칸을 두 번 클릭: 그 칸의 색을 편집
 * - 색 1/색 2 표시를 클릭: 두 색을 맞바꿈
 * 색이 바뀌면 부모에 WM_PALETTE_COLORCHANGED를 보냅니다.
 */
class CColorPalette : public CWnd
{
public:
    /** @brief 기본 색 칸 수 */
    static constexpr int kColumns = 14;
    static constexpr int kRows = 2;

    CColorPalette();

    /**
     * @brief 창을 만듭니다.
     * @param rect 부모 클라이언트 좌표의 위치
     * @param pParent 부모 창
     * @param nID 컨트롤 ID
     * @return 성공하면 TRUE
     */
    BOOL Create(const CRect& rect, CWnd* pParent, UINT nID);

    /**
     * @brief 주어진 높이에서 필요한 너비를 계산합니다.
     * @param height 컨트롤 높이(px)
     * @param gap 칸 사이 간격(px)
     */
    static int CalcWidth(int height, int gap);

    COLORREF GetPrimary() const { return m_primary; }
    COLORREF GetSecondary() const { return m_secondary; }

    /** @brief 색 1을 정합니다. 부모에 알리지 않습니다. */
    void SetPrimary(COLORREF color);
    /** @brief 색 2를 정합니다. 부모에 알리지 않습니다. */
    void SetSecondary(COLORREF color);

    /**
     * @brief 색 편집 대화 상자를 띄워 색 1을 바꿉니다.
     * @return 바꿨으면 true
     */
    bool EditPrimary();

protected:
    afx_msg void OnPaint();
    afx_msg BOOL OnEraseBkgnd(CDC* pDC);
    afx_msg void OnLButtonDown(UINT nFlags, CPoint point);
    afx_msg void OnLButtonDblClk(UINT nFlags, CPoint point);
    afx_msg void OnRButtonDown(UINT nFlags, CPoint point);
    afx_msg void OnRButtonUp(UINT nFlags, CPoint point);
    DECLARE_MESSAGE_MAP()

private:
    /** @brief 현재 크기에서의 배치 */
    struct Layout
    {
        CRect swatchArea;   ///< 색 1/색 2 표시 영역
        CRect primary;      ///< 색 1 사각형
        CRect secondary;    ///< 색 2 사각형
        int gridLeft = 0;   ///< 색 칸 시작 x
        int cell = 0;       ///< 색 칸 한 변
        int gap = 0;        ///< 칸 사이 간격
    };

    Layout CalcLayout() const;
    CRect CellRect(const Layout& layout, int index) const;
    /** @brief 점이 있는 색 칸 번호. 없으면 -1 */
    int HitTestCell(CPoint point) const;
    int Scale(int value) const;
    void NotifyParent();

    std::array<COLORREF, kColumns * kRows> m_cells; ///< 기본 색 (윗줄 → 아랫줄)
    COLORREF m_primary = RGB(0, 0, 0);
    COLORREF m_secondary = RGB(255, 255, 255);
    COLORREF m_customColors[16] = {};               ///< 색 대화 상자의 사용자 지정 색
};

