    }
}

void CMyPaintDlg::OnFillComboChanged()
{
    const int selection = m_fillCombo.GetCurSel();
    if (selection != CB_ERR)
    {
        m_canvas.SetFillMode(static_cast<ShapeFillMode>(selection));
    }
}

