param([string]$OutPng)
Add-Type -ReferencedAssemblies System.Drawing -TypeDefinition @"
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
public static class Drv {
  [DllImport("user32.dll")] public static extern IntPtr FindWindow(string c, string t);
  [DllImport("user32.dll")] public static extern IntPtr GetDlgItem(IntPtr h, int id);
  [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr hdc, uint f);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern uint GetDpiForWindow(IntPtr h);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L, T, R, B; }
  static IntPtr P(int x, int y) { return (IntPtr)((y << 16) | (x & 0xFFFF)); }
  public static IntPtr Dlg, Canvas;
  public static void Init() {
    Dlg = FindWindow(null, "MyPaint");
    Canvas = GetDlgItem(Dlg, 1014);
  }
  public static void Tool(int i) { SendMessage(GetDlgItem(Dlg, 1000 + i), 0x00F5 /*BM_CLICK*/, IntPtr.Zero, IntPtr.Zero); }
  public static void Combo(int id, int sel) {
    IntPtr c = GetDlgItem(Dlg, id);
    SendMessage(c, 0x014E /*CB_SETCURSEL*/, (IntPtr)sel, IntPtr.Zero);
    SendMessage(Dlg, 0x0111, (IntPtr)((1 /*CBN_SELCHANGE*/ << 16) | id), c);
  }
  // Drag in image coordinates (origin offset added). btn: 0 left, 1 right. shift: hold MK_SHIFT
  public static void Drag(int off, int[] pts, int btn, bool shift) {
    uint down = btn == 0 ? 0x0201u : 0x0204u, up = btn == 0 ? 0x0202u : 0x0205u;
    int mk = (btn == 0 ? 1 : 2) | (shift ? 4 : 0);
    SendMessage(Canvas, down, (IntPtr)mk, P(pts[0] + off, pts[1] + off));
    for (int i = 2; i < pts.Length; i += 2) SendMessage(Canvas, 0x0200, (IntPtr)mk, P(pts[i] + off, pts[i + 1] + off));
    int n = pts.Length;
    SendMessage(Canvas, up, (IntPtr)(shift ? 4 : 0), P(pts[n - 2] + off, pts[n - 1] + off));
  }
  public static void Shot(string path) {
    RECT r; GetWindowRect(Dlg, out r);
    using (var bmp = new Bitmap(r.R - r.L, r.B - r.T)) {
      using (var g = Graphics.FromImage(bmp)) { IntPtr hdc = g.GetHdc(); PrintWindow(Dlg, hdc, 2); g.ReleaseHdc(hdc); }
      bmp.Save(path, ImageFormat.Png);
    }
  }
}
"@
[Drv]::Init()
$dpi = [Drv]::GetDpiForWindow([Drv]::Dlg)
$off = [int][Math]::Floor(8 * $dpi / 96)
"dpi=$dpi off=$off canvas=$([Drv]::Canvas)"

# Pencil zigzag (size 1)
[Drv]::Tool(0); [Drv]::Drag($off, @(20,20, 60,60, 100,20, 140,60), 0, $false)
# Brush wave (default 8px) with right button = color 2 (white) on black? Use left.
[Drv]::Tool(1); [Drv]::Drag($off, @(20,100, 50,90, 80,110, 110,90, 140,110, 170,100), 0, $false)
# Line, Shift-snapped
[Drv]::Tool(5); [Drv]::Drag($off, @(200,20, 260,35, 330,45), 0, $true)
[Drv]::Drag($off, @(200,60, 300,140), 0, $false)
# Rectangle outline+fill (fill combo index 1) and ellipse with shift (circle)
[Drv]::Tool(6); [Drv]::Combo(1011, 1); [Drv]::Drag($off, @(20,160, 150,260), 0, $false)
[Drv]::Tool(7); [Drv]::Combo(1011, 0); [Drv]::Drag($off, @(180,160, 300,200), 0, $true)
# Fill inside circle then outside region of rect stays
[Drv]::Tool(3); [Drv]::Drag($off, @(240,220), 0, $false)
# Eraser through pencil zigzag
[Drv]::Tool(2); [Drv]::Drag($off, @(10,40, 150,40), 0, $false)
# Cancel test: start a rectangle with left, press right button -> should cancel
[Drv]::Tool(6)
[Drv]::SendMessage([Drv]::Canvas, 0x0201, [IntPtr]1, [IntPtr](((300+$off) -shl 16) -bor (350+$off))) | Out-Null
[Drv]::SendMessage([Drv]::Canvas, 0x0200, [IntPtr]1, [IntPtr](((380+$off) -shl 16) -bor (500+$off))) | Out-Null
[Drv]::SendMessage([Drv]::Canvas, 0x0204, [IntPtr]3, [IntPtr](((380+$off) -shl 16) -bor (500+$off))) | Out-Null
[Drv]::SendMessage([Drv]::Canvas, 0x0202, [IntPtr]0, [IntPtr](((380+$off) -shl 16) -bor (500+$off))) | Out-Null
Start-Sleep -Milliseconds 300
[Drv]::Shot($OutPng)
"saved"

