CRect CCanvasSurface::FloodFill(CPoint seed, COLORREF color)
{
    CRect dirty;
    dirty.SetRectEmpty();
    if (!Contains(seed))
    {
        return dirty;
    }

    uint32_t* pixels = Pixels();
    const uint32_t replacement = ToPixel(color);
    const uint32_t target = pixels[static_cast<size_t>(seed.y) * m_width + seed.x] & kRgbMask;
    if (target == replacement)
    {
        return dirty; // 이미 같은 색
    }

    auto at = [&](int x, int y) -> uint32_t& { return pixels[static_cast<size_t>(y) * m_width + x]; };
    auto isTarget = [&](int x, int y) { return (at(x, y) & kRgbMask) == target; };

    // 스캔라인 채우기: 가로 구간을 한 번에 채우고, 위/아래 줄에서 새 구간의 시작점만 스택에 넣습니다.
    std::vector<POINT> stack;
    stack.push_back(seed);

