void CCanvasSurface::BlendFillEdge(const std::vector<uint8_t>& filled, uint32_t target, uint32_t replacement,
                                   const CRect& filledBounds)
{
    // 채운 영역 바로 바깥 픽셀은 앤티에일리어싱으로 "원래 색(target)"과 "경계 색"이 섞여 있을 수 있습니다.
