bool CCanvasSurface::ContentEquals(CCanvasSurface& other)
{
    if (&other == this)
    {
        return true;
    }
    if (!IsValid() || !other.IsValid() || GetSize() != other.GetSize())
    {
        return IsValid() == other.IsValid() && GetSize() == other.GetSize();
