    // 알파 바이트는 GDI/GDI+가 제각각 쓰므로 RGB만 비교
    const uint32_t* a = Pixels();
    const uint32_t* b = other.Pixels();
    const size_t count = static_cast<size_t>(m_width) * m_height;
    for (size_t i = 0; i < count; ++i)
    {
        if (((a[i] ^ b[i]) & kRgbMask) != 0)
        {
            return false;
        }
    }
    return true;
}

