using System.Drawing.Imaging;
using System.Runtime.InteropServices;
public static class T {
  [DllImport("user32.dll")] public static extern IntPtr GetDlgItem(IntPtr h, int id);
  [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr h, uint m, IntPtr w, IntPtr l);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern int GetClassName(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr hdc, uint f);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern uint SendInput(uint n, INPUT[] i, int size);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L, T, R, B; }
  [StructLayout(LayoutKind.Sequential)] public struct KEYBDINPUT { public ushort wVk; public ushort wScan; public uint dwFlags; public uint time; public IntPtr extra; }
  [StructLayout(LayoutKind.Explicit, Size = 40)] public struct INPUT { [FieldOffset(0)] public uint type; [FieldOffset(8)] public KEYBDINPUT ki; }
  static INPUT K(ushort vk, ushort scan, uint flags) { var i = new INPUT(); i.type = 1; i.ki.wVk = vk; i.ki.wScan = scan; i.ki.dwFlags = flags; return i; }
  public static void Chord(params ushort[] vks) {
    var list = new System.Collections.Generic.List<INPUT>();
    foreach (var v in vks) list.Add(K(v, 0, 0));
    for (int i = vks.Length - 1; i >= 0; --i) list.Add(K(vks[i], 0, 2));
    SendInput((uint)list.Count, list.ToArray(), Marshal.SizeOf(typeof(INPUT)));
    Thread.Sleep(400);
  }
  public static void Type(string s) {
    foreach (char c in s) { var a = new INPUT[] { K(0, c, 4), K(0, c, 4 | 2) }; SendInput(2, a, Marshal.SizeOf(typeof(INPUT))); }
    Thread.Sleep(200);
  }
  public static string Text(IntPtr h) { var sb = new StringBuilder(512); GetWindowText(h, sb, 512); return sb.ToString(); }
  public static string Cls(IntPtr h) { var sb = new StringBuilder(256); GetClassName(h, sb, 256); return sb.ToString(); }
  public static IntPtr Dlg, Canvas, TabBar;
  static IntPtr P(int x, int y) { return (IntPtr)((y << 16) | (x & 0xFFFF)); }
  public static void Init(long h) { Dlg = (IntPtr)h; Canvas = GetDlgItem(Dlg, 1014); TabBar = GetDlgItem(Dlg, 1016); }
  public static void Drag(int[] pts) {
    int off = 8;
    SendMessage(Canvas, 0x0201, (IntPtr)1, P(pts[0] + off, pts[1] + off));
    for (int i = 2; i < pts.Length; i += 2) SendMessage(Canvas, 0x0200, (IntPtr)1, P(pts[i] + off, pts[i + 1] + off));
    SendMessage(Canvas, 0x0202, IntPtr.Zero, P(pts[pts.Length - 2] + off, pts[pts.Length - 1] + off));
  }
  public static void ClickTab(int x, int y) { SendMessage(TabBar, 0x0201, (IntPtr)1, P(x, y)); SendMessage(TabBar, 0x0202, IntPtr.Zero, P(x, y)); }
  public static void Shot(string path) {
    RECT r; GetWindowRect(Dlg, out r);
    using (var bmp = new Bitmap(r.R - r.L, r.B - r.T)) {
      using (var g = Graphics.FromImage(bmp)) { IntPtr hdc = g.GetHdc(); PrintWindow(Dlg, hdc, 2); g.ReleaseHdc(hdc); }
      bmp.Save(path, ImageFormat.Png);
    }
  }
}
