using System; using System.Text; using System.Runtime.InteropServices; using System.Collections.Generic;
public static class E {
  public delegate bool CB(IntPtr h, IntPtr l);
  [DllImport("user32.dll")] public static extern bool EnumWindows(CB cb, IntPtr l);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern int GetClassName(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  public static List<string> List(uint pid) { var r = new List<string>(); EnumWindows((h, l) => { uint p; GetWindowThreadProcessId(h, out p); if (p == pid && IsWindowVisible(h)) { var a = new StringBuilder(256); var b = new StringBuilder(256); GetWindowText(h, a, 256); GetClassName(h, b, 256); r.Add(h + " " + b + " '" + a + "'"); } return true; }, IntPtr.Zero); return r; }
}
"@
$p = Get-Process MyPaint; [E]::List([uint32]$p.Id)

