1	/**
2	 * @file MyPaintDlg.cpp
3	 * @brief 주 대화 상자 클래스 구현
4	 */
5	#include "pch.h"
6	#include "MyPaint.h"
7	#include "MyPaintDlg.h"
8	#include "ImageFile.h"
9	
10	#ifdef _DEBUG
11	#define new DEBUG_NEW
12	#endif
13	
14	namespace
15	{
16	    // 배치 값은 모두 96 DPI 기준 px이며 Scale()로 바꿔 씁니다.
17	    constexpr int kPadding = 8;         ///< 창 가장자리 여백
18	    constexpr int kBandTop = 6;         ///< 도구 모음 위 여백
19	    constexpr int kButtonWidth = 62;    ///< 도구 버튼 너비
20	    constexpr int kButtonHeight = 26;   ///< 도구 버튼, 콤보 줄 높이
21	    constexpr int kGap = 4;             ///< 컨트롤 사이 간격
22	    constexpr int kToolColumns = 4;     ///< 도구 버튼 열 수
23	    constexpr int kGroupSpacing = 12;   ///< 묶음과 구분선 사이 간격
24	    constexpr int kLabelWidth = 44;     ///< "굵기", "채우기" 글자 너비
25	    constexpr int kComboWidth = 150;    ///< 콤보 너비
26	    constexpr int kComboDropHeight = 240; ///< 콤보 목록 높이
