367	int CMyPaintDlg::AddNewTab()
368	{
369	    auto document = std::make_unique<CPaintDocument>(m_nextUntitledNumber);
370	    if (!document->Create(kDefaultImageWidth, kDefaultImageHeight))
371	    {
372	        MessageBox(L"새 그림을 만들지 못했습니다. 메모리가 부족할 수 있습니다.", L"MyPaint", MB_ICONERROR);
373	        return -1;
374	    }
