384	void CMyPaintDlg::ActivateTab(int index)
385	{
386	    if (index < 0 || index >= static_cast<int>(m_documents.size()))
387	    {
388	        return;
389	    }
390	    m_activeTab = index;
391	    m_canvas.SetDocument(m_documents[index].get()); // 도구 설정은 캔버스에 그대로 남음
392	    m_tabBar.SetActiveTab(index);
