494	bool CMyPaintDlg::AskSavePath(const CPaintDocument& document, CString& path)
495	{
496	    // 필터 순서와 kExtensions 순서가 같아야 함 (nFilterIndex는 1부터)
497	    static const wchar_t kFilter[] = L"PNG (*.png)|*.png|BMP (*.bmp)|*.bmp|JPEG (*.jpg;*.jpeg)|*.jpg;*.jpeg||";
498	    static const wchar_t* const kExtensions[] = { L".png", L".bmp", L".jpg" };
499	
500	    const CString currentPath = document.GetFilePath();
501	    CString fileName;
502	    CString folder;
503	    DWORD filterIndex = 1; // PNG 기본
504	    if (currentPath.IsEmpty())
505	    {
506	        fileName = document.GetTitle() + L".png";
507	    }
508	    else
509	    {
510	        fileName = ::PathFindFileName(currentPath);
511	        folder = currentPath.Left(static_cast<int>(::PathFindFileName(currentPath) - static_cast<LPCWSTR>(currentPath)));
512	        ImageFormat format;
513	        if (ImageFormatFromPath(currentPath, format))
514	        {
515	            filterIndex = static_cast<DWORD>(format) + 1;
516	        }
517	    }
518	
519	    CFileDialog dlg(FALSE, L"png", fileName, OFN_OVERWRITEPROMPT | OFN_PATHMUSTEXIST | OFN_HIDEREADONLY, kFilter, this);
520	    dlg.m_ofn.nFilterIndex = filterIndex;
521	    if (!folder.IsEmpty())
522	    {
523	        dlg.m_ofn.lpstrInitialDir = folder;
524	    }
525	    if (dlg.DoModal() != IDOK)
526	    {
527	        return false;
528	    }
529	
530	    CString chosen = dlg.GetPathName();
531	    ImageFormat format;
532	    if (!ImageFormatFromPath(chosen, format))
533	    {
534	        // 확장자가 없거나 지원하지 않으면 고른 형식의 확장자를 붙임.
535	        // 이 경우 대화 상자의 덮어쓰기 확인을 거치지 않았으므로 직접 확인
536	        const DWORD selected = dlg.m_ofn.nFilterIndex;
537	        chosen += kExtensions[(selected >= 1 && selected <= _countof(kExtensions)) ? selected - 1 : 0];
538	        if (::PathFileExists(chosen))
539	        {
540	            CString message;
541	            message.Format(L"%s이(가) 이미 있습니다.\n바꾸시겠습니까?", static_cast<LPCWSTR>(::PathFindFileName(chosen)));
542	            if (MessageBox(message, L"다른 이름으로 저장 확인", MB_YESNO | MB_ICONWARNING) != IDYES)
543	            {
544	                return false;
545	            }
546	        }
547	    }
548	    path = chosen;
549	    return true;
550	}
