109	    ::GetMonitorInfo(::MonitorFromWindow(GetSafeHwnd(), MONITOR_DEFAULTTONEAREST), &mi);
110	    const CRect work(mi.rcWork);
111	    CRect rc(0, 0, max(m_minClientWidth, Scale(kInitialClientWidth)), Scale(kInitialClientHeight));
112	    ::AdjustWindowRectExForDpi(&rc, GetStyle(), FALSE, GetExStyle(), m_dpi);
113	    const int width = min(rc.Width(), work.Width());
114	    const int height = min(rc.Height(), work.Height());
115	    SetWindowPos(nullptr, work.left + (work.Width() - width) / 2, work.top + (work.Height() - height) / 2,
116	                 width, height, SWP_NOZORDER | SWP_NOACTIVATE);
117	    LayoutControls();
