187	void CMyPaintDlg::LayoutControls()
188	{
189	    if (m_canvas.GetSafeHwnd() == nullptr)
190	    {
191	        return;
192	    }
193	
194	    CRect rcClient;
195	    GetClientRect(&rcClient);
196	
197	    const int top = Scale(kBandTop);
198	    const int buttonW = Scale(kButtonWidth);
199	    const int buttonH = Scale(kButtonHeight);
200	    const int gap = Scale(kGap);
201	    const int bandH = 2 * buttonH + gap; // 컨트롤 두 줄
202	    const int spacing = Scale(kGroupSpacing);
203	    int x = Scale(kPadding);
204	
205	    // 도구
206	    for (int i = 0; i < kToolCount; ++i)
207	    {
208	        const int col = i % kToolColumns;
209	        const int row = i / kToolColumns;
210	        m_toolButtons[i].MoveWindow(x + col * (buttonW + gap), top + row * (buttonH + gap), buttonW, buttonH);
211	    }
212	    const int toolRows = (kToolCount + kToolColumns - 1) / kToolColumns;
213	    m_groupRects[GroupTools].SetRect(x, top, x + kToolColumns * buttonW + (kToolColumns - 1) * gap,
214	                                     top + toolRows * buttonH + (toolRows - 1) * gap);
215	    x = m_groupRects[GroupTools].right + 2 * spacing;
216	
217	    // 모양: 굵기 / 채우기
218	    const int labelW = Scale(kLabelWidth);
219	    const int comboW = Scale(kComboWidth);
220	    auto placeRow = [&](CStatic& label, CComboBox& combo, int rowTop) {
221	        label.MoveWindow(x, rowTop, labelW, buttonH);
222	        // 드롭다운 콤보의 높이는 목록 높이이고, 닫힌 높이는 글꼴로 정해지므로 만든 뒤 가운데로 맞춤
223	        combo.MoveWindow(x + labelW, rowTop, comboW, Scale(kComboDropHeight));
224	        CRect rcCombo;
225	        combo.GetWindowRect(&rcCombo);
226	        combo.MoveWindow(x + labelW, rowTop + (buttonH - rcCombo.Height()) / 2, comboW, Scale(kComboDropHeight));
227	    };
228	    placeRow(m_sizeLabel, m_sizeCombo, top);
229	    placeRow(m_fillLabel, m_fillCombo, top + buttonH + gap);
230	    m_groupRects[GroupShape].SetRect(x, top, x + labelW + comboW, top + bandH);
231	    x = m_groupRects[GroupShape].right + 2 * spacing;
232	
233	    // 색: 팔레트 + 색 편집 버튼
234	    const int paletteGap = Scale(kPaletteGap);
235	    const int paletteH = bandH - 2 * gap;
236	    const int paletteW = CColorPalette::CalcWidth(paletteH, paletteGap);
237	    m_palette.MoveWindow(x, top + (bandH - paletteH) / 2, paletteW, paletteH);
238	    const int editX = x + paletteW + spacing;
239	    m_editColorButton.MoveWindow(editX, top, Scale(kEditButtonWidth), bandH);
240	    m_groupRects[GroupColors].SetRect(x, top, editX + Scale(kEditButtonWidth), top + bandH);
241	
242	    m_minClientWidth = m_groupRects[GroupColors].right + Scale(kPadding);
243	    m_captionTop = top + bandH + gap / 2;
244	    m_bandBottom = m_captionTop + Scale(kCaptionHeight) + gap / 2;
245	
246	    // 상태 표시줄 (CCS_BOTTOM이라 WM_SIZE를 받으면 스스로 아래에 붙음)
247	    m_statusBar.SendMessage(WM_SIZE);
248	    CRect rcStatus;
249	    m_statusBar.GetWindowRect(&rcStatus);
250	    const int widths[StatusPartCount] = { Scale(150), Scale(300), -1 };
251	    m_statusBar.SetParts(StatusPartCount, const_cast<int*>(widths));
252	
253	    // 탭 표시줄: 도구 모음 바로 아래. 선택된 탭이 아래 캔버스와 이어짐
254	    const int tabTop = m_bandBottom + 1;
255	    const int tabH = m_tabBar.GetPreferredHeight();
256	    m_tabBar.MoveWindow(0, tabTop, rcClient.Width(), tabH);
257	
258	    // 캔버스: 탭 표시줄과 상태 표시줄 사이 전체
259	    const int canvasTop = tabTop + tabH;
260	    m_canvas.MoveWindow(0, canvasTop, rcClient.Width(), max(0, rcClient.Height() - rcStatus.Height() - canvasTop));
261	
262	    InvalidateRect(CRect(0, 0, rcClient.Width(), m_bandBottom + 1));
263	}
