265	void CMyPaintDlg::OnPaint()
266	{
267	    CPaintDC dc(this);
268	    CRect rcClient;
269	    GetClientRect(&rcClient);
270	
271	    // 묶음 이름
272	    CFont* oldFont = dc.SelectObject(&m_font);
273	    dc.SetBkMode(TRANSPARENT);
274	    dc.SetTextColor(::GetSysColor(COLOR_GRAYTEXT));
275	    static const wchar_t* const kCaptions[GroupCount] = { L"도구", L"모양", L"색" };
276	    for (int i = 0; i < GroupCount; ++i)
277	    {
278	        CRect rcCaption(m_groupRects[i].left, m_captionTop, m_groupRects[i].right, m_captionTop + Scale(kCaptionHeight));
279	        dc.DrawText(kCaptions[i], -1, &rcCaption, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
280	    }
281	    dc.SelectObject(oldFont);
282	
283	    // 묶음 사이 세로 구분선, 도구 모음 아래 가로 구분선
284	    const COLORREF lineColor = ::GetSysColor(COLOR_3DSHADOW);
285	    const int spacing = Scale(kGroupSpacing);
286	    for (int i = 0; i + 1 < GroupCount; ++i)
287	    {
288	        const int lineX = m_groupRects[i].right + spacing;
289	        dc.FillSolidRect(lineX, m_groupRects[i].top, 1, m_bandBottom - m_groupRects[i].top - Scale(kGap), lineColor);
290	    }
291	    dc.FillSolidRect(0, m_bandBottom, rcClient.Width(), 1, lineColor);
292	}
