398	bool CMyPaintDlg::CloseTab(int index)
399	{
400	    if (index < 0 || index >= static_cast<int>(m_documents.size()))
401	    {
402	        return false;
403	    }
404	    if (!ConfirmSaveChanges(index)) // 저장할지 물을 때 그 탭을 보여 주므로 선택이 바뀔 수 있음
405	    {
406	        return false;
407	    }
408	
409	    const bool wasActive = (index == m_activeTab);
410	    if (wasActive)
411	    {
412	        m_canvas.SetDocument(nullptr); // 지울 문서를 캔버스가 더 가리키지 않게
413	    }
414	    m_documents.erase(m_documents.begin() + index);
415	    m_tabBar.RemoveTab(index);
416	
417	    if (m_documents.empty())
418	    {
419	        m_activeTab = -1;
420	        AddNewTab(); // 창은 항상 탭을 하나 이상 가짐
421	    }
422	    else if (wasActive)
423	    {
424	        // 크롬처럼 오른쪽 탭으로, 마지막 탭이었다면 왼쪽 탭으로
425	        ActivateTab(min(index, static_cast<int>(m_documents.size()) - 1));
426	    }
427	    else
428	    {
429	        if (index < m_activeTab)
430	        {
431	            --m_activeTab;
432	        }
433	        m_tabBar.SetActiveTab(m_activeTab);
434	    }
435	    return true;
436	}
