438	bool CMyPaintDlg::ConfirmSaveChanges(int index)
439	{
440	    CPaintDocument& document = *m_documents[index];
441	    if (!document.IsModified())
442	    {
443	        return true;
444	    }
445	    if (index != m_activeTab)
446	    {
447	        ActivateTab(index); // 무엇을 저장하는지 보이게
448	    }
449	
450	    CString message;
451	    message.Format(L"'%s'의 변경 내용을 저장할까요?", static_cast<LPCWSTR>(document.GetTitle()));
452	    switch (MessageBox(message, L"MyPaint", MB_YESNOCANCEL | MB_ICONWARNING))
453	    {
454	    case IDYES: return SaveTab(index, false); // 저장을 취소하거나 실패하면 닫지 않음
455	    case IDNO:  return true;
456	    default:    return false;
457	    }
458	}
