460	bool CMyPaintDlg::SaveTab(int index, bool askPath)
461	{
462	    CPaintDocument& document = *m_documents[index];
463	
464	    // 처음 저장하는 탭이면 경로를 묻고, 이미 저장한 탭이면 묻지 않고 덮어씀
465	    CString path = document.GetFilePath();
466	    if (path.IsEmpty() || askPath)
467	    {
468	        if (!AskSavePath(document, path))
469	        {
470	            return false;
471	        }
472	    }
473	
474	    CString error;
475	    {
476	        CWaitCursor wait;
477	        if (!SaveImageFile(document.Surface(), path, error))
478	        {
479	            MessageBox(error, L"저장 실패", MB_ICONERROR);
480	            return false;
481	        }
482	    }
483	
484	    document.SetFilePath(path);
485	    document.SetModified(false);
486	    UpdateTabTitle(index);
487	    if (index == m_activeTab)
488	    {
489	        UpdateWindowTitle();
490	    }
491	    return true;
492	}
