658	    const ToolType tool = m_canvas.GetTool();
659	    const ToolInfo& info = GetToolInfo(tool);
660	
661	    m_sizeCombo.EnableWindow(info.usesSize);
662	    m_sizeLabel.EnableWindow(info.usesSize);
663	    const int size = m_canvas.GetToolSize(tool);
664	    int selection = -1;
665	    for (int i = 0; i < m_sizeCombo.GetCount(); ++i)
666	    {
667	        if (static_cast<int>(m_sizeCombo.GetItemData(i)) == size)
668	        {
669	            selection = i;
670	            break;
671	        }
672	    }
673	    m_sizeCombo.SetCurSel(info.usesSize ? selection : -1);
674	
675	    m_fillCombo.EnableWindow(info.usesFillMode);
676	    m_fillLabel.EnableWindow(info.usesFillMode);
677	
678	    m_statusBar.SetText(info.hint, StatusHint, 0);
679	}
