        return false;
    }
    if (!surface.Create(static_cast<int>(width), static_cast<int>(height), RGB(255, 255, 255)))
    {
        errorMessage = L"그림을 담을 메모리를 만들지 못했습니다. 메모리가 부족할 수 있습니다.";
        return false;
    }

    // 어떤 픽셀 형식이든(팔레트, 24비트, 알파 포함 등) 32비트 ARGB로 받아서 변환
