    Gdiplus::BitmapData data{};
    if (bitmap.LockBits(&rect, Gdiplus::ImageLockModeRead, PixelFormat32bppARGB, &data) != Gdiplus::Ok)
    {
        errorMessage = L"그림 픽셀을 읽지 못했습니다.";
        return false;
    }

