                                                            static_cast<INT_PTR>(y) * data.Stride);
        uint32_t* row = dst + static_cast<size_t>(y) * width;
        for (UINT x = 0; x < width; ++x)
        {
            const uint32_t argb = src[x];
            const uint32_t a = argb >> 24;
            if (a == 255)
