            auto over = [a](uint32_t c) { return (c * a + 255 * (255 - a) + 127) / 255; };
            const uint32_t r = over((argb >> 16) & 0xFF);
            const uint32_t g = over((argb >> 8) & 0xFF);
            const uint32_t b = over(argb & 0xFF);
            row[x] = (r << 16) | (g << 8) | b;
        }
