        return false;
    }
    m_filePath = path;
    m_modified = false;
    m_scroll = CPoint(0, 0);
    return true;
}

CString CPaintDocument::GetTitle() const
{
    if (!m_filePath.IsEmpty())
    {
        return CString(::PathFindFileName(m_filePath));
