203	    for (int size : kSizeChoices)
204	    {
205	        CString text;
206	        text.Format(L"%dpx", size);
207	        const int index = m_sizeCombo.AddString(text);
208	        m_sizeCombo.SetItemData(index, static_cast<DWORD_PTR>(size));
209	    }
210	
211	    m_fillLabel.Create(L"채우기", WS_CHILD | WS_VISIBLE | WS_GROUP | SS_LEFT | SS_CENTERIMAGE, empty, this);
212	    m_fillCombo.Create(WS_CHILD | WS_VISIBLE | WS_TABSTOP | WS_VSCROLL | CBS_DROPDOWNLIST, empty, this, IDC_FILL_COMBO);
213	    // 항목 순서는 ShapeFillMode 값과 같음
214	    m_fillCombo.AddString(L"윤곽선만");
215	    m_fillCombo.AddString(L"윤곽선 + 색 2로 채우기");
216	    m_fillCombo.AddString(L"채우기만");
217	    m_fillCombo.SetCurSel(static_cast<int>(m_canvas.GetFillMode()));
218	
219	    m_palette.Create(empty, this, IDC_PALETTE);
220	    m_editColorButton.Create(L"색 편집", WS_CHILD | WS_VISIBLE | WS_TABSTOP | WS_GROUP | BS_PUSHBUTTON | BS_MULTILINE,
221	                             empty, this, IDC_EDIT_COLOR);
222	
223	    m_tabBar.Create(empty, this, IDC_TABBAR);
224	    m_tabBar.SetActiveColor(kCanvasWorkspaceColor);
225	    m_canvas.Create(empty, this, IDC_CANVAS);
226	    m_statusBar.Create(WS_CHILD | WS_VISIBLE | SBARS_SIZEGRIP | CCS_BOTTOM, empty, this, IDC_STATUSBAR);
227	
228	    // 파일 단추에 마우스를 올리면 단축키를 알려 줌
229	    if (m_toolTip.Create(this, TTS_ALWAYSTIP))
230	    {
231	        for (int i = 0; i < kFileButtonCount; ++i)
232	        {
233	            m_toolTip.AddTool(&m_fileButtons[i], kFileButtons[i].tip);
234	        }
235	        m_toolTip.Activate(TRUE);
236	    }
237	}
238	
239	void CMyPaintDlg::LayoutControls()
240	{
241	    if (m_canvas.GetSafeHwnd() == nullptr)
242	    {
243	        return;
244	    }
245	
246	    CRect rcClient;
247	    GetClientRect(&rcClient);
248	
249	    const int top = Scale(kBandTop);
250	    const int buttonW = Scale(kButtonWidth);
251	    const int buttonH = Scale(kButtonHeight);
252	    const int gap = Scale(kGap);
253	    const int bandH = 2 * buttonH + gap; // 컨트롤 두 줄
254	    const int spacing = Scale(kGroupSpacing);
255	    int x = Scale(kPadding);
256	
257	    // 파일: 2×2 단추. 열 너비는 그 열에서 가장 긴 글자에 맞춤 ("다른 이름으로 저장")
258	    {
259	        int columnWidth[kFileColumns];
260	        for (int& width : columnWidth)
261	        {
262	            width = Scale(kFileButtonMinWidth);
263	        }
264	        CClientDC dc(this);
265	        CFont* oldFont = (m_font.GetSafeHandle() != nullptr) ? dc.SelectObject(&m_font) : nullptr;
266	        for (int i = 0; i < kFileButtonCount; ++i)
267	        {
268	            const int textWidth = dc.GetTextExtent(kFileButtons[i].text).cx + Scale(kButtonTextPadding);
269	            columnWidth[i % kFileColumns] = max(columnWidth[i % kFileColumns], textWidth);
270	        }
271	        if (oldFont != nullptr)
272	        {
273	            dc.SelectObject(oldFont);
274	        }
275	
276	        for (int i = 0; i < kFileButtonCount; ++i)
277	        {
278	            const int col = i % kFileColumns;
279	            const int row = i / kFileColumns;
280	            const int buttonX = x + (col == 0 ? 0 : columnWidth[0] + gap);
281	            m_fileButtons[i].MoveWindow(buttonX, top + row * (buttonH + gap), columnWidth[col], buttonH);
282	        }
283	        m_groupRects[GroupFile].SetRect(x, top, x + columnWidth[0] + gap + columnWidth[1], top + bandH);
284	        x = m_groupRects[GroupFile].right + 2 * spacing;
285	    }
286	
287	    // 도구
288	    for (int i = 0; i < kToolCount; ++i)
289	    {
290	        const int col = i % kToolColumns;
291	        const int row = i / kToolColumns;
292	        m_toolButtons[i].MoveWindow(x + col * (buttonW + gap), top + row * (buttonH + gap), buttonW, buttonH);
293	    }
294	    const int toolRows = (kToolCount + kToolColumns - 1) / kToolColumns;
295	    m_groupRects[GroupTools].SetRect(x, top, x + kToolColumns * buttonW + (kToolColumns - 1) * gap,
296	                                     top + toolRows * buttonH + (toolRows - 1) * gap);
297	    x = m_groupRects[GroupTools].right + 2 * spacing;
298	
299	    // 모양: 굵기 / 채우기
300	    const int labelW = Scale(kLabelWidth);
301	    const int comboW = Scale(kComboWidth);
302	    auto placeRow = [&](CStatic& label, CComboBox& combo, int rowTop) {
303	        label.MoveWindow(x, rowTop, labelW, buttonH);
304	        // 드롭다운 콤보의 높이는 목록 높이이고, 닫힌 높이는 글꼴로 정해지므로 만든 뒤 가운데로 맞춤
305	        combo.MoveWindow(x + labelW, rowTop, comboW, Scale(kComboDropHeight));
306	        CRect rcCombo;
307	        combo.GetWindowRect(&rcCombo);
308	        combo.MoveWindow(x + labelW, rowTop + (buttonH - rcCombo.Height()) / 2, comboW, Scale(kComboDropHeight));
309	    };
310	    placeRow(m_sizeLabel, m_sizeCombo, top);
311	    placeRow(m_fillLabel, m_fillCombo, top + buttonH + gap);
312	    m_groupRects[GroupShape].SetRect(x, top, x + labelW + comboW, top + bandH);
313	    x = m_groupRects[GroupShape].right + 2 * spacing;
314	
315	    // 색: 팔레트 + 색 편집 버튼
316	    const int paletteGap = Scale(kPaletteGap);
317	    const int paletteH = bandH - 2 * gap;
318	    const int paletteW = CColorPalette::CalcWidth(paletteH, paletteGap);
319	    m_palette.MoveWindow(x, top + (bandH - paletteH) / 2, paletteW, paletteH);
320	    const int editX = x + paletteW + spacing;
321	    m_editColorButton.MoveWindow(editX, top, Scale(kEditButtonWidth), bandH);
322	    m_groupRects[GroupColors].SetRect(x, top, editX + Scale(kEditButtonWidth), top + bandH);
323	
324	    m_minClientWidth = m_groupRects[GroupColors].right + Scale(kPadding);
325	    m_captionTop = top + bandH + gap / 2;
326	    m_bandBottom = m_captionTop + Scale(kCaptionHeight) + gap / 2;
327	
328	    // 상태 표시줄 (CCS_BOTTOM이라 WM_SIZE를 받으면 스스로 아래에 붙음)
329	    m_statusBar.SendMessage(WM_SIZE);
330	    CRect rcStatus;
331	    m_statusBar.GetWindowRect(&rcStatus);
332	    const int widths[StatusPartCount] = { Scale(150), Scale(300), -1 };
333	    m_statusBar.SetParts(StatusPartCount, const_cast<int*>(widths));
334	
335	    // 탭 표시줄: 도구 모음 바로 아래. 선택된 탭이 아래 캔버스와 이어짐
336	    const int tabTop = m_bandBottom + 1;
337	    const int tabH = m_tabBar.GetPreferredHeight();
338	    m_tabBar.MoveWindow(0, tabTop, rcClient.Width(), tabH);
339	
340	    // 캔버스: 탭 표시줄과 상태 표시줄 사이 전체
341	    const int canvasTop = tabTop + tabH;
342	    m_canvas.MoveWindow(0, canvasTop, rcClient.Width(), max(0, rcClient.Height() - rcStatus.Height() - canvasTop));
343	
344	    InvalidateRect(CRect(0, 0, rcClient.Width(), m_bandBottom + 1));
345	}
346	
347	void CMyPaintDlg::OnPaint()
348	{
349	    CPaintDC dc(this);
350	    CRect rcClient;
351	    GetClientRect(&rcClient);
352	
353	    // 묶음 이름
354	    CFont* oldFont = dc.SelectObject(&m_font);
355	    dc.SetBkMode(TRANSPARENT);
356	    dc.SetTextColor(::GetSysColor(COLOR_GRAYTEXT));
357	    static const wchar_t* const kCaptions[GroupCount] = { L"파일", L"도구", L"모양", L"색" };
358	    for (int i = 0; i < GroupCount; ++i)
359	    {
360	        CRect rcCaption(m_groupRects[i].left, m_captionTop, m_groupRects[i].right, m_captionTop + Scale(kCaptionHeight));
361	        dc.DrawText(kCaptions[i], -1, &rcCaption, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
362	    }
363	    dc.SelectObject(oldFont);
364	
365	    // 묶음 사이 세로 구분선, 도구 모음 아래 가로 구분선
366	    const COLORREF lineColor = ::GetSysColor(COLOR_3DSHADOW);
367	    const int spacing = Scale(kGroupSpacing);
368	    for (int i = 0; i + 1 < GroupCount; ++i)
369	    {
370	        const int lineX = m_groupRects[i].right + spacing;
371	        dc.FillSolidRect(lineX, m_groupRects[i].top, 1, m_bandBottom - m_groupRects[i].top - Scale(kGap), lineColor);
372	    }
373	    dc.FillSolidRect(0, m_bandBottom, rcClient.Width(), 1, lineColor);
374	}
375	
376	void CMyPaintDlg::OnSize(UINT nType, int cx, int cy)
377	{
378	    CDialog::OnSize(nType, cx, cy);
379	    if (nType != SIZE_MINIMIZED)
380	    {
381	        LayoutControls();
382	    }
383	}
384	
385	void CMyPaintDlg::OnGetMinMaxInfo(MINMAXINFO* lpMMI)
386	{
387	    CDialog::OnGetMinMaxInfo(lpMMI);
388	    if (m_minClientWidth > 0)
389	    {
390	        CRect rc(0, 0, m_minClientWidth, Scale(kMinClientHeight));
391	        ::AdjustWindowRectExForDpi(&rc, GetStyle(), FALSE, GetExStyle(), m_dpi);
392	        lpMMI->ptMinTrackSize.x = rc.Width();
393	        lpMMI->ptMinTrackSize.y = rc.Height();
394	    }
395	}
