397	LRESULT CMyPaintDlg::OnDpiChanged(WPARAM wParam, LPARAM lParam)
398	{
399	    m_dpi = LOWORD(wParam);
400	    UpdateUiFont();
401	
402	    const RECT* suggested = reinterpret_cast<const RECT*>(lParam);
403	    SetWindowPos(nullptr, suggested->left, suggested->top, suggested->right - suggested->left,
404	                 suggested->bottom - suggested->top, SWP_NOZORDER | SWP_NOACTIVATE);
405	    LayoutControls();
406	    Invalidate();
407	    return 0;
408	}
