694	bool CMyPaintDlg::AskSavePath(const CPaintDocument& document, CString& path)
695	{
696	    // 필터 순서와 kExtensions 순서가 같아야 함 (nFilterIndex는 1부터)
697	    static const wchar_t kFilter[] = L"PNG (*.png)|*.png|BMP (*.bmp)|*.bmp|JPEG (*.jpg;*.jpeg)|*.jpg;*.jpeg||";
698	    static const wchar_t* const kExtensions[] = { L".png", L".bmp", L".jpg" };
699	
700	    const CString currentPath = document.GetFilePath();
701	    CString fileName;
702	    CString folder;
703	    DWORD filterIndex = 1; // PNG 기본
704	    if (currentPath.IsEmpty())
705	    {
706	        fileName = document.GetTitle() + L".png";
707	    }
708	    else
709	    {
710	        fileName = ::PathFindFileName(currentPath);
711	        folder = currentPath.Left(static_cast<int>(::PathFindFileName(currentPath) - static_cast<LPCWSTR>(currentPath)));
712	        ImageFormat format;
713	        if (ImageFormatFromPath(currentPath, format))
714	        {
715	            filterIndex = static_cast<DWORD>(format) + 1;
716	        }
717	    }
718	
719	    CFileDialog dlg(FALSE, L"png", fileName, OFN_OVERWRITEPROMPT | OFN_PATHMUSTEXIST | OFN_HIDEREADONLY, kFilter, this);
720	    dlg.m_ofn.nFilterIndex = filterIndex;
721	    if (!folder.IsEmpty())
722	    {
723	        dlg.m_ofn.lpstrInitialDir = folder;
724	    }
725	    if (dlg.DoModal() != IDOK)
726	    {
727	        return false;
728	    }
729	
730	    CString chosen = dlg.GetPathName();
731	    ImageFormat format;
732	    if (!ImageFormatFromPath(chosen, format))
733	    {
734	        // 확장자가 없거나 지원하지 않으면 고른 형식의 확장자를 붙임.
735	        // 이 경우 대화 상자의 덮어쓰기 확인을 거치지 않았으므로 직접 확인
736	        const DWORD selected = dlg.m_ofn.nFilterIndex;
737	        chosen += kExtensions[(selected >= 1 && selected <= _countof(kExtensions)) ? selected - 1 : 0];
738	        if (::PathFileExists(chosen))
739	        {
740	            CString message;
741	            message.Format(L"%s이(가) 이미 있습니다.\n바꾸시겠습니까?", static_cast<LPCWSTR>(::PathFindFileName(chosen)));
742	            if (MessageBox(message, L"다른 이름으로 저장 확인", MB_YESNO | MB_ICONWARNING) != IDYES)
743	            {
744	                return false;
745	            }
746	        }
747	    }
748	    path = chosen;
749	    return true;
750	}
