'@
[W]::SetProcessDPIAware() | Out-Null

function Tips($pid_) {
    foreach ($t in [M]::AllTop($pid_)) { if ([W]::Cls($t) -eq 'tooltips_class32') { "{0} visible={1}" -f $t, [W]::IsWindowVisible($t) } }
}

$p = Start-Process $Exe -PassThru
$main = [IntPtr]::Zero
for ($i = 0; $i -lt 50 -and $main -eq [IntPtr]::Zero; $i++) { Start-Sleep -Milliseconds 200; $p.Refresh(); $main = $p.MainWindowHandle }
$pid_ = [uint32]$p.Id
Start-Sleep -Milliseconds 600
$old = New-Object 'W+POINT'; [W]::GetCursorPos([ref]$old) | Out-Null
try {
    Write-Host "tooltip windows at start:"; Tips $pid_ | ForEach-Object { Write-Host "  $_" }
    [W]::Topmost($main, $true); Start-Sleep -Milliseconds 300
    $btn = [W]::GetDlgItem($main, 1018)
    $br = New-Object 'W+RECT'; [W]::GetWindowRect($btn, [ref]$br) | Out-Null
    $mx = [int](($br.L + $br.R) / 2); $my = [int](($br.T + $br.B) / 2)
    Write-Host "button rect $($br.L),$($br.T)-$($br.R),$($br.B) foreground=$([W]::GetForegroundWindow() -eq $main)"

    Write-Host "A) SetCursorPos"
    [W]::SetCursorPos($mx - 8, $my) | Out-Null; Start-Sleep -Milliseconds 100
    [W]::SetCursorPos($mx, $my) | Out-Null
    for ($t = 0; $t -lt 15; $t++) { Start-Sleep -Milliseconds 200; $v = Tips $pid_; if ($v -match 'visible=True') { break } }
    Write-Host "  after $(($t + 1) * 200) ms:"; Tips $pid_ | ForEach-Object { Write-Host "  $_" }

    Write-Host "B) SendInput absolute move"
    [M]::MoveTo($mx + 300, $my + 300) | Out-Null; Start-Sleep -Milliseconds 300
    [M]::MoveTo($mx - 8, $my) | Out-Null; Start-Sleep -Milliseconds 80
    [M]::MoveTo($mx, $my) | Out-Null
    for ($t = 0; $t -lt 15; $t++) { Start-Sleep -Milliseconds 200; $v = Tips $pid_; if ($v -match 'visible=True') { break } }
    Write-Host "  after $(($t + 1) * 200) ms:"; Tips $pid_ | ForEach-Object { Write-Host "  $_" }
    $cur = New-Object 'W+POINT'; [W]::GetCursorPos([ref]$cur) | Out-Null
    Write-Host "  cursor now $($cur.X),$($cur.Y)"
    $bmp = [W]::CaptureRect($br.L - 20, $br.T - 10, 420, 90); $bmp.Save((Join-Path $scratch 'shots\diag-tooltip.png')); $bmp.Dispose()
}
finally {
    [W]::SetCursorPos($old.X, $old.Y) | Out-Null
    Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue
}

