$p = Start-Process $Exe -PassThru
$main = [IntPtr]::Zero
for ($i = 0; $i -lt 50 -and $main -eq [IntPtr]::Zero; $i++) { Start-Sleep -Milliseconds 200; $p.Refresh(); $main = $p.MainWindowHandle }
