        $dlg = [W]::WaitDialog($pid_, $main, 5000)
        Write-Host ("[{0}] Ctrl+O shows the open dialog :: sent={1} dialog='{2}'" -f $(if ($sent -and $dlg -ne [IntPtr]::Zero) { 'PASS' } else { 'FAIL' }), $sent, [W]::Text($dlg))
        if ($dlg -ne [IntPtr]::Zero) { [W]::PostMessage($dlg, [W]::WM_CLOSE, [IntPtr]::Zero, [IntPtr]::Zero) | Out-Null; [W]::WaitGone($dlg, 3000) | Out-Null }
    } else {
        Write-Host '[SKIP] Ctrl+O: MyPaint is not the foreground window'
    }

    $tips = @([M2]::AllTop($pid_) | Where-Object { [W]::Cls($_) -eq 'tooltips_class32' })
    Write-Host "tooltip windows: $($tips.Count)"
    foreach ($tip in $tips) {
        $count = [W]::SendMessage($tip, $TTM_GETTOOLCOUNT, [IntPtr]::Zero, [IntPtr]::Zero).ToInt32()
        $before = [W]::SendMessage($tip, $TTM_GETCURRENTTOOL, [IntPtr]::Zero, [IntPtr]::Zero).ToInt32()
        # A mouse move posted to the open button goes through the message loop, so PreTranslateMessage relays it
        $btn = [W]::GetDlgItem($main, 1018)
        [W]::PostMessage($btn, [W]::WM_MOUSEMOVE, [IntPtr]::Zero, [W]::LParam(12, 10)) | Out-Null
        Start-Sleep -Milliseconds 150
        $after = [W]::SendMessage($tip, $TTM_GETCURRENTTOOL, [IntPtr]::Zero, [IntPtr]::Zero).ToInt32()
        # Same for a control that has no tooltip (a tool button): the current tool should go away
        $toolBtn = [W]::GetDlgItem($main, 1000)
        [W]::PostMessage($toolBtn, [W]::WM_MOUSEMOVE, [IntPtr]::Zero, [W]::LParam(12, 10)) | Out-Null
        Start-Sleep -Milliseconds 150
        $other = [W]::SendMessage($tip, $TTM_GETCURRENTTOOL, [IntPtr]::Zero, [IntPtr]::Zero).ToInt32()
        Write-Host ("[{0}] tooltip {1}: tools={2} (expect 4), current tool before={3} after move over open button={4} after move over pencil button={5}" -f `
            $(if ($count -eq 4 -and $before -eq 0 -and $after -ne 0 -and $other -eq 0) { 'PASS' } else { 'FAIL' }), $tip, $count, $before, $after, $other)
    }
}
finally {
    Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue
}

