471	int CMyPaintDlg::AppendDocument(std::unique_ptr<CPaintDocument> document)
472	{
473	    const int index = static_cast<int>(m_documents.size()); // 크롬처럼 맨 끝에 추가
474	    m_tabBar.InsertTab(index, document->GetTitle());
475	    m_documents.push_back(std::move(document));
476	    return index;
477	}
478	
479	void CMyPaintDlg::ReplaceDocument(int index, std::unique_ptr<CPaintDocument> document)
480	{
481	    const bool active = (index == m_activeTab);
482	    if (active)
483	    {
484	        m_canvas.SetDocument(nullptr); // 지울 문서를 캔버스가 더 가리키지 않게
485	    }
486	    m_documents[index] = std::move(document);
487	    UpdateTabTitle(index);
488	    if (active)
489	    {
490	        ActivateTab(index);
491	    }
492	}
493	
494	int CMyPaintDlg::FindTabByPath(const CString& path) const
495	{
496	    for (int i = 0; i < static_cast<int>(m_documents.size()); ++i)
497	    {
498	        const CString& tabPath = m_documents[i]->GetFilePath();
499	        if (!tabPath.IsEmpty() && tabPath.CompareNoCase(path) == 0)
500	        {
501	            return i;
502	        }
503	    }
504	    return -1;
505	}
506	
507	void CMyPaintDlg::OpenImageFiles(const std::vector<CString>& paths)
508	{
509	    // 지금 탭이 아무것도 안 그린 빈 탭이면 첫 파일은 그 자리에 엶 (빈 탭이 남지 않게)
510	    int reusableTab = (m_activeTab >= 0 && m_documents[m_activeTab]->IsPristine()) ? m_activeTab : -1;
511	    int tabToShow = -1;
512	    CString failures;
513	    {
514	        CWaitCursor wait;
515	        for (const CString& path : paths)
516	        {
517	            const int existing = FindTabByPath(path);
518	            if (existing >= 0)
519	            {
520	                tabToShow = existing; // 이미 열린 파일은 다시 열지 않고 그 탭으로 감
521	                continue;
522	            }
523	
524	            auto document = std::make_unique<CPaintDocument>(0);
525	            CString error;
526	            if (!document->LoadFromFile(path, error))
527	            {
528	                failures.AppendFormat(L"\n\n%s\n%s", static_cast<LPCWSTR>(::PathFindFileName(path)), static_cast<LPCWSTR>(error));
529	                continue;
530	            }
531	            if (reusableTab >= 0)
532	            {
533	                ReplaceDocument(reusableTab, std::move(document));
534	                tabToShow = reusableTab;
535	                reusableTab = -1;
536	            }
537	            else
538	            {
539	                tabToShow = AppendDocument(std::move(document));
540	            }
541	        }
542	    }
543	
544	    if (tabToShow >= 0)
545	    {
546	        ActivateTab(tabToShow);
547	    }
548	    if (!failures.IsEmpty())
549	    {
550	        MessageBox(L"다음 파일을 열지 못했습니다." + failures, L"열기 실패", MB_ICONERROR);
551	    }
552	}
553	
554	bool CMyPaintDlg::AskOpenPaths(std::vector<CString>& paths)
555	{
556	    static const wchar_t kFilter[] =
557	        L"그림 파일 (*.png;*.bmp;*.jpg;*.jpeg)|*.png;*.bmp;*.jpg;*.jpeg|"
558	        L"PNG (*.png)|*.png|BMP (*.bmp)|*.bmp|JPEG (*.jpg;*.jpeg)|*.jpg;*.jpeg|모든 파일 (*.*)|*.*||";
559	
560	    CFileDialog dlg(TRUE, nullptr, nullptr, OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST | OFN_HIDEREADONLY | OFN_ALLOWMULTISELECT,
561	                    kFilter, this);
562	    // 여러 파일을 고르면 이름이 이어 붙으므로 넉넉한 버퍼를 줌
563	    std::vector<wchar_t> buffer(64 * 1024, L'\0');
564	    dlg.m_ofn.lpstrFile = buffer.data();
565	    dlg.m_ofn.nMaxFile = static_cast<DWORD>(buffer.size());
566	
567	    // 지금 탭이 파일이면 그 폴더에서 시작
568	    CString folder;
569	    if (m_activeTab >= 0 && !m_documents[m_activeTab]->GetFilePath().IsEmpty())
570	    {
571	        folder = FolderOf(m_documents[m_activeTab]->GetFilePath());
572	        dlg.m_ofn.lpstrInitialDir = folder;
573	    }
574	
575	    if (dlg.DoModal() != IDOK)
