395	void CCanvasWnd::OnMouseHWheel(UINT, short zDelta, CPoint)
396	{
397	    ScrollTo(m_scroll.x + ::MulDiv(zDelta, Scale(kWheelScroll), WHEEL_DELTA), m_scroll.y);
398	}
