403	
404	void CCanvasWnd::BeginStroke(CPoint ptClient, MouseButton button)
405	{
406	    SetFocus();
407	
408	    const CPoint pt = ClientToImage(ptClient);
409	    if (!Image().IsValid() || !Image().Contains(pt))
410	    {
411	        return; // 그림 밖에서는 그리기를 시작하지 않음
412	    }
413	    if (!m_backup.CopyFrom(Image()))
414	    {
415	        return; // 되돌릴 수 없으면 그리지 않음
416	    }
417	
418	    m_stroking = true;
419	    m_strokeButton = button;
420	    m_lastImagePt = pt;
421	    SetCapture();
422	
423	    StrokeParams params;
424	    params.button = button;
425	    params.fore = (button == MouseButton::Left) ? m_primary : m_secondary;
426	    params.back = (button == MouseButton::Left) ? m_secondary : m_primary;
427	    params.size = GetToolSize(m_tool);
428	    params.fillMode = m_fillMode;
429	    CurrentTool().Begin(*this, pt, params);
430	}
431	
432	void CCanvasWnd::EndStroke(CPoint ptClient, UINT nFlags)
433	{
434	    const CPoint pt = ClientToImage(ptClient);
435	    m_stroking = false; // 먼저 내려야 캡처 해제 알림에서 두 번 마무리하지 않음
436	    CurrentTool().End(*this, pt, (nFlags & MK_SHIFT) != 0);
437	    if (GetCapture() == this)
438	    {
439	        ReleaseCapture();
440	    }
441	    MarkModifiedIfChanged();
442	}
443	
444	void CCanvasWnd::OnLButtonDown(UINT, CPoint point)
445	{
446	    if (m_stroking)
447	    {
448	        // 오른쪽 버튼으로 그리는 중에 왼쪽 버튼을 누르면 취소 (그림판과 같음)
449	        if (m_strokeButton != MouseButton::Left)
450	        {
451	            CancelStroke();
452	        }
453	        return;
454	    }
455	    BeginStroke(point, MouseButton::Left);
456	}
457	
458	void CCanvasWnd::OnLButtonUp(UINT nFlags, CPoint point)
459	{
460	    if (m_stroking && m_strokeButton == MouseButton::Left)
461	    {
462	        EndStroke(point, nFlags);
463	    }
464	}
