1	#pragma once
2	
3	/**
4	 * @file CanvasWnd.h
5	 * @brief 그림을 보여 주고 마우스로 그리게 하는 캔버스 창
6	 */
7	
8	#include "CanvasSurface.h"
9	#include "PaintDocument.h"
10	#include "PaintTools.h"
11	
12	#include <array>
13	#include <memory>
14	
15	/**
16	 * @brief 캔버스 창.
17	 *
18	 * 그림(CCanvasSurface)과 현재 도구, 색, 굵기를 가지고, 마우스 입력을 도구에 전달합니다.
19	 * 그림은 현재 탭의 문서(CPaintDocument)가 가지고, 캔버스는 그 문서를 가리키기만 합니다.
20	 * 도구와 색 설정은 캔버스가 가지므로 탭을 바꿔도 유지됩니다.
21	 * 그림이 창보다 크면 스크롤 막대로 이동합니다. 상태가 바뀌면 부모 창에
22	 * WM_CANVAS_CURSOR, WM_CANVAS_COLORPICKED, WM_CANVAS_MODIFIED 메시지를 보냅니다.
23	 */
24	class CCanvasWnd : public CWnd, private IToolHost
25	{
26	public:
27	    CCanvasWnd();
28	    ~CCanvasWnd() override;
29	
30	    /**
31	     * @brief 창을 만듭니다.
32	     * @param rect 부모 클라이언트 좌표의 위치
33	     * @param pParent 부모 창
34	     * @param nID 컨트롤 ID
35	     * @return 성공하면 TRUE
36	     */
37	    BOOL Create(const CRect& rect, CWnd* pParent, UINT nID);
38	
39	    /**
40	     * @brief 보여 주고 그릴 문서를 바꿉니다 (탭 전환).
41	     *
42	     * 그리는 중이었다면 취소하고, 이전 문서의 스크롤 위치를 저장한 뒤 새 문서의 위치로 돌아갑니다.
43	     * 도구, 굵기, 색 같은 설정은 그대로 유지합니다.
44	     * @param document 새 문서. 캔버스는 소유하지 않으며 nullptr이면 빈 화면
45	     */
46	    void SetDocument(CPaintDocument* document);
47	
48	    /** @brief 현재 문서 (없으면 nullptr) */
49	    CPaintDocument* GetDocument() const { return m_document; }
50	
51	    /** @brief 그림 크기(px). 문서가 없으면 0 */
52	    CSize GetImageSize() const;
53	
54	    /** @brief 현재 도구를 바꿉니다. 그리는 중이었다면 취소합니다. */
55	    void SetTool(ToolType tool);
56	    /** @brief 현재 도구 */
57	    ToolType GetTool() const { return m_tool; }
58	
59	    /** @brief 도구별 굵기를 정합니다. */
60	    void SetToolSize(ToolType tool, int size);
61	    /** @brief 도구별 굵기 */
62	    int GetToolSize(ToolType tool) const { return m_toolSizes[ToIndex(tool)]; }
63	
64	    /** @brief 도형 채우기 방식을 정합니다. */
65	    void SetFillMode(ShapeFillMode mode) { m_fillMode = mode; }
66	    /** @brief 도형 채우기 방식 */
67	    ShapeFillMode GetFillMode() const { return m_fillMode; }
68	
