208	void CCanvasWnd::OnPaint()
209	{
210	    CPaintDC dc(this);
211	    const CRect rcPaint(dc.m_ps.rcPaint);
212	    if (rcPaint.IsRectEmpty())
213	    {
214	        return;
215	    }
216	
217	    // 다시 그릴 영역만큼의 이중 버퍼
218	    CDC memDC;
219	    memDC.CreateCompatibleDC(&dc);
220	    CBitmap buffer;
221	    buffer.CreateCompatibleBitmap(&dc, rcPaint.Width(), rcPaint.Height());
222	    CBitmap* oldBitmap = memDC.SelectObject(&buffer);
223	    memDC.SetViewportOrg(-rcPaint.left, -rcPaint.top);
224	
225	    memDC.FillSolidRect(rcPaint, kCanvasWorkspaceColor);
226	
227	    if (Image().IsValid())
228	    {
229	        const CPoint origin = ImageOrigin();
230	        const CSize size = Image().GetSize();
231	        const CRect rcImage(origin, size);
232	
233	        CRect rcShadow(rcImage);
234	        rcShadow.OffsetRect(Scale(kShadowOffset), Scale(kShadowOffset));
235	        memDC.FillSolidRect(rcShadow, kShadowColor);
236	
237	        CRect rcBlit;
238	        if (rcBlit.IntersectRect(rcImage, rcPaint))
239	        {
240	            memDC.BitBlt(rcBlit.left, rcBlit.top, rcBlit.Width(), rcBlit.Height(), &Image().GetDC(),
241	                         rcBlit.left - origin.x, rcBlit.top - origin.y, SRCCOPY);
242	        }
243	
244	        // 미리보기와 도구 커서는 그림 좌표로 그림
245	        memDC.SetViewportOrg(0, 0);
246	        {
247	            Gdiplus::Graphics g(memDC.GetSafeHdc());
248	            g.TranslateTransform(static_cast<Gdiplus::REAL>(origin.x - rcPaint.left),
249	                                 static_cast<Gdiplus::REAL>(origin.y - rcPaint.top));
250	            g.SetClip(Gdiplus::Rect(0, 0, size.cx, size.cy));
251	
252	            CPaintTool& tool = CurrentTool();
253	            tool.DrawOverlay(g);
254	            if (m_hoverVisible && tool.HasCustomCursor())
255	            {
256	                tool.DrawCursor(g, m_hoverImagePt, GetToolSize(m_tool));
257	            }
258	        }
259	    }
260	
261	    memDC.SetViewportOrg(0, 0);
262	    dc.BitBlt(rcPaint.left, rcPaint.top, rcPaint.Width(), rcPaint.Height(), &memDC, 0, 0, SRCCOPY);
263	    memDC.SelectObject(oldBitmap);
264	}
