276	void CCanvasWnd::UpdateScrollBars()
277	{
278	    if (m_updatingScrollBars || GetSafeHwnd() == nullptr)
279	    {
280	        return;
281	    }
282	    m_updatingScrollBars = true;
283	
284	    const CSize image = Image().GetSize();
285	    const int margin = Scale(kImageMargin);
286	    const CSize content(image.cx + 2 * margin, image.cy + 2 * margin);
287	
288	    // 한쪽 스크롤 막대가 나타나면 다른 쪽 클라이언트 크기가 줄어들므로 두 번 계산
289	    for (int pass = 0; pass < 2; ++pass)
290	    {
291	        CRect rcClient;
292	        GetClientRect(&rcClient);
293	
294	        SCROLLINFO si{};
295	        si.cbSize = sizeof(si);
296	        si.fMask = SIF_RANGE | SIF_PAGE | SIF_POS;
297	        si.nMin = 0;
298	
299	        si.nMax = content.cx - 1;
300	        si.nPage = static_cast<UINT>(rcClient.Width());
301	        si.nPos = m_scroll.x;
302	        SetScrollInfo(SB_HORZ, &si, TRUE);
303	
304	        si.nMax = content.cy - 1;
305	        si.nPage = static_cast<UINT>(rcClient.Height());
306	        si.nPos = m_scroll.y;
307	        SetScrollInfo(SB_VERT, &si, TRUE);
308	    }
309	
310	    // 범위를 벗어난 위치는 시스템이 잘라 주므로 다시 읽음
311	    m_scroll.x = GetScrollPos(SB_HORZ);
312	    m_scroll.y = GetScrollPos(SB_VERT);
313	
314	    m_updatingScrollBars = false;
315	    Invalidate(FALSE);
316	}
317	
318	void CCanvasWnd::ScrollTo(int x, int y)
319	{
320	    SCROLLINFO si{};
321	    si.cbSize = sizeof(si);
322	    si.fMask = SIF_RANGE | SIF_PAGE;
323	
324	    GetScrollInfo(SB_HORZ, &si);
325	    const int maxX = max(0, si.nMax - static_cast<int>(si.nPage) + 1);
326	    GetScrollInfo(SB_VERT, &si);
327	    const int maxY = max(0, si.nMax - static_cast<int>(si.nPage) + 1);
328	
329	    const CPoint target(max(0, min(x, maxX)), max(0, min(y, maxY)));
330	    if (target == m_scroll)
331	    {
332	        return;
333	    }
334	    m_scroll = target;
335	    SetScrollPos(SB_HORZ, m_scroll.x, TRUE);
336	    SetScrollPos(SB_VERT, m_scroll.y, TRUE);
337	    Invalidate(FALSE);
338	}
