381	BOOL CCanvasWnd::OnMouseWheel(UINT nFlags, short zDelta, CPoint)
382	{
383	    const int amount = ::MulDiv(-zDelta, Scale(kWheelScroll), WHEEL_DELTA);
384	    if (nFlags & MK_SHIFT)
385	    {
386	        ScrollTo(m_scroll.x + amount, m_scroll.y); // Shift + 휠: 가로 스크롤
387	    }
388	    else
389	    {
390	        ScrollTo(m_scroll.x, m_scroll.y + amount);
391	    }
392	    return TRUE;
393	}
