432	void CCanvasWnd::EndStroke(CPoint ptClient, UINT nFlags)
433	{
434	    const CPoint pt = ClientToImage(ptClient);
435	    m_stroking = false; // 먼저 내려야 캡처 해제 알림에서 두 번 마무리하지 않음
436	    CurrentTool().End(*this, pt, (nFlags & MK_SHIFT) != 0);
437	    if (GetCapture() == this)
438	    {
439	        ReleaseCapture();
440	    }
441	    MarkModifiedIfChanged();
442	}
