444	void CCanvasWnd::OnLButtonDown(UINT, CPoint point)
445	{
446	    if (m_stroking)
447	    {
448	        // 오른쪽 버튼으로 그리는 중에 왼쪽 버튼을 누르면 취소 (그림판과 같음)
449	        if (m_strokeButton != MouseButton::Left)
450	        {
451	            CancelStroke();
452	        }
453	        return;
454	    }
455	    BeginStroke(point, MouseButton::Left);
456	}
457	
458	void CCanvasWnd::OnLButtonUp(UINT nFlags, CPoint point)
459	{
460	    if (m_stroking && m_strokeButton == MouseButton::Left)
461	    {
462	        EndStroke(point, nFlags);
463	    }
464	}
465	
466	void CCanvasWnd::OnRButtonDown(UINT, CPoint point)
467	{
468	    if (m_stroking)
469	    {
470	        if (m_strokeButton != MouseButton::Right)
471	        {
472	            CancelStroke();
473	        }
474	        return;
475	    }
476	    BeginStroke(point, MouseButton::Right);
477	}
478	
479	void CCanvasWnd::OnRButtonUp(UINT nFlags, CPoint point)
480	{
481	    // 기본 처리를 하지 않아 WM_CONTEXTMENU가 생기지 않게 함
482	    if (m_stroking && m_strokeButton == MouseButton::Right)
483	    {
484	        EndStroke(point, nFlags);
485	    }
486	}
487	
488	void CCanvasWnd::OnMouseMove(UINT nFlags, CPoint point)
489	{
490	    if (!m_trackingMouse)
491	    {
492	        TRACKMOUSEEVENT tme{};
493	        tme.cbSize = sizeof(tme);
494	        tme.dwFlags = TME_LEAVE;
495	        tme.hwndTrack = GetSafeHwnd();
496	        m_trackingMouse = ::TrackMouseEvent(&tme) != FALSE;
497	    }
498	
499	    const CPoint pt = ClientToImage(point);
500	    const bool inside = Image().Contains(pt);
501	    NotifyCursor(pt, inside);
502	    UpdateHover(point, inside);
503	
504	    if (m_stroking)
505	    {
506	        ApplyCursor(inside); // 캡처 중에는 WM_SETCURSOR가 오지 않음
507	        m_lastImagePt = pt;
508	        CurrentTool().Drag(*this, pt, (nFlags & MK_SHIFT) != 0);
509	    }
510	}
511	
512	void CCanvasWnd::OnMouseLeave()
513	{
514	    m_trackingMouse = false;
515	    NotifyCursor(CPoint(0, 0), false);
516	    UpdateHover(CPoint(0, 0), false);
517	}
518	
519	void CCanvasWnd::OnCaptureChanged(CWnd* pWnd)
520	{
521	    // 다른 창이 캡처를 가져가면(예: Alt+Tab) 마지막 위치에서 그리기를 마무리
522	    if (m_stroking && pWnd != this)
523	    {
524	        m_stroking = false;
525	        CurrentTool().End(*this, m_lastImagePt, false);
526	        MarkModifiedIfChanged();
527	    }
528	    CWnd::OnCaptureChanged(pWnd);
529	}
530	
531	BOOL CCanvasWnd::OnSetCursor(CWnd* pWnd, UINT nHitTest, UINT message)
532	{
533	    if (nHitTest == HTCLIENT)
534	    {
535	        CPoint pt;
536	        ::GetCursorPos(&pt);
537	        ScreenToClient(&pt);
538	        ApplyCursor(Image().Contains(ClientToImage(pt)));
539	        return TRUE;
540	    }
541	    return CWnd::OnSetCursor(pWnd, nHitTest, message);
542	}
543	
544	void CCanvasWnd::ApplyCursor(bool insideImage)
545	{
546	    if (!insideImage)
547	    {
548	        ::SetCursor(::LoadCursor(nullptr, IDC_ARROW));
549	    }
550	    else if (CurrentTool().HasCustomCursor())
551	    {
552	        ::SetCursor(nullptr); // 도구가 직접 그린 커서만 보이게
553	    }
554	    else
555	    {
556	        ::SetCursor(::LoadCursor(nullptr, IDC_CROSS));
557	    }
558	}
559	
560	void CCanvasWnd::UpdateHover(CPoint ptClient, bool inside)
561	{
562	    const bool visible = inside && CurrentTool().HasCustomCursor();
563	    const CPoint pt = ClientToImage(ptClient);
564	    if (visible == m_hoverVisible && (!visible || pt == m_hoverImagePt))
565	    {
566	        return;
567	    }
568	    if (m_hoverVisible)
569	    {
570	        InvalidateRect(HoverClientRect(), FALSE);
571	    }
572	    m_hoverVisible = visible;
573	    m_hoverImagePt = pt;
574	    if (m_hoverVisible)
575	    {
576	        InvalidateRect(HoverClientRect(), FALSE);
577	    }
578	}
579	
580	CRect CCanvasWnd::HoverClientRect() const
581	{
582	    const int size = GetToolSize(m_tool);
583	    CRect rc(m_hoverImagePt.x - size / 2, m_hoverImagePt.y - size / 2,
584	             m_hoverImagePt.x - size / 2 + size, m_hoverImagePt.y - size / 2 + size);
585	    rc.InflateRect(2, 2);
586	    return ImageToClient(rc);
587	}
588	
589	void CCanvasWnd::NotifyCursor(CPoint ptImage, bool inside)
590	{
591	    GetParent()->SendMessage(WM_CANVAS_CURSOR, inside ? 1 : 0, MAKELPARAM(ptImage.x, ptImage.y));
592	}
