16	    // 배치 값은 모두 96 DPI 기준 px이며 Scale()로 바꿔 씁니다.
17	    constexpr int kBarHeight = 36;      ///< 표시줄 높이
18	    constexpr int kTabTop = 6;          ///< 탭 위 여백
19	    constexpr int kSidePadding = 8;     ///< 왼쪽/오른쪽 여백
20	    constexpr int kCornerRadius = 8;    ///< 탭 모서리 반지름 (아래쪽 바깥 곡선도 같은 크기)
21	    constexpr int kTabMaxWidth = 220;   ///< 탭 최대 너비
22	    constexpr int kTabMinWidth = 56;    ///< 탭 최소 너비
23	    constexpr int kTextPadding = 12;    ///< 탭 왼쪽 글자 여백
24	    constexpr int kCloseSize = 18;      ///< × 단추 크기
25	    constexpr int kCloseMargin = 8;     ///< × 단추 오른쪽 여백
26	    constexpr int kCloseMinTabWidth = 90; ///< 이보다 좁은 탭은 선택된 탭에만 × 표시 (크롬과 같음)
27	    constexpr int kNewTabSize = 28;     ///< + 단추 크기
28	    constexpr int kNewTabGap = 6;       ///< 마지막 탭과 + 단추 사이
29	
30	    const COLORREF kInactiveTextColor = RGB(70, 74, 80);
31	    const COLORREF kActiveTextColor = RGB(20, 20, 20);
32	    const COLORREF kSeparatorColor = RGB(165, 170, 180);
33	    const Color kGlyphColor(255, 80, 84, 90);       ///< ×, ●, + 색
34	    const Color kButtonHoverColor(40, 0, 0, 0);     ///< 단추 위에 마우스가 있을 때 덧칠할 색
35	
36	    Color ToColor(COLORREF c, BYTE alpha = 255)
37	    {
38	        return Color(alpha, GetRValue(c), GetGValue(c), GetBValue(c));
39	    }
40	
41	    COLORREF Mix(COLORREF a, COLORREF b, int percentB)
42	    {
43	        auto mix = [percentB](int x, int y) { return x + (y - x) * percentB / 100; };
44	        return RGB(mix(GetRValue(a), GetRValue(b)), mix(GetGValue(a), GetGValue(b)), mix(GetBValue(a), GetBValue(b)));
45	    }
46	
47	    /** @brief 위쪽은 둥글고 아래쪽은 바깥으로 휘어 바닥과 이어지는 크롬 탭 모양 */
48	    void AddTabShape(GraphicsPath& path, const CRect& rc, int radius)
49	    {
50	        const REAL r = static_cast<REAL>(radius);
51	        const REAL l = static_cast<REAL>(rc.left), t = static_cast<REAL>(rc.top);
52	        const REAL rt = static_cast<REAL>(rc.right), b = static_cast<REAL>(rc.bottom);
53	        path.StartFigure();
54	        path.AddArc(l - 2 * r, b - 2 * r, 2 * r, 2 * r, 90.0f, -90.0f);   // 왼쪽 아래 바깥 곡선
55	        path.AddArc(l, t, 2 * r, 2 * r, 180.0f, 90.0f);                   // 왼쪽 위
56	        path.AddArc(rt - 2 * r, t, 2 * r, 2 * r, 270.0f, 90.0f);          // 오른쪽 위
57	        path.AddArc(rt, b - 2 * r, 2 * r, 2 * r, 180.0f, -90.0f);         // 오른쪽 아래 바깥 곡선
58	        path.CloseFigure();
59	    }
60	
61	    void DrawCross(Graphics& g, const CRect& rc, REAL penWidth)
62	    {
63	        Pen pen(kGlyphColor, penWidth);
64	        const REAL inset = rc.Width() * 0.3f;
65	        const REAL l = rc.left + inset, t = rc.top + inset;
66	        const REAL r = rc.right - inset, b = rc.bottom - inset;
67	        g.DrawLine(&pen, PointF(l, t), PointF(r, b));
68	        g.DrawLine(&pen, PointF(r, t), PointF(l, b));
69	    }
70	}
