107	
108	void CTabBar::InsertTab(int index, const CString& title)
109	{
110	    index = max(0, min(index, GetTabCount()));
111	    Tab tab;
112	    tab.title = title;
113	    m_tabs.insert(m_tabs.begin() + index, tab);
114	    if (m_active >= index)
115	    {
116	        ++m_active;
117	    }
118	    m_hover = HitResult{};
119	    Invalidate(FALSE);
120	}
121	
122	void CTabBar::RemoveTab(int index)
123	{
124	    if (index < 0 || index >= GetTabCount())
125	    {
126	        return;
127	    }
128	    m_tabs.erase(m_tabs.begin() + index);
129	    if (m_active == index)
130	    {
131	        m_active = -1;
132	    }
133	    else if (m_active > index)
134	    {
135	        --m_active;
136	    }
137	    m_hover = HitResult{};
138	    m_pressedClose = -1;
139	    Invalidate(FALSE);
140	}
141	
142	void CTabBar::SetTab(int index, const CString& title, bool modified)
143	{
144	    if (index < 0 || index >= GetTabCount())
145	    {
146	        return;
147	    }
148	    m_tabs[index].title = title;
149	    m_tabs[index].modified = modified;
150	    Invalidate(FALSE);
151	}
152	
153	void CTabBar::SetActiveTab(int index)
154	{
155	    m_active = (index >= 0 && index < GetTabCount()) ? index : -1;
156	    Invalidate(FALSE);
157	}
158	
159	// ---------------------------------------------------------------------------
160	// 배치
161	// ---------------------------------------------------------------------------
162	
163	int CTabBar::TabWidth() const
164	{
165	    if (m_tabs.empty())
166	    {
167	        return Scale(kTabMaxWidth);
168	    }
169	    CRect rcClient;
170	    GetClientRect(&rcClient);
171	    const int left = Scale(kSidePadding) + Scale(kCornerRadius);
172	    const int reserved = Scale(kNewTabGap) + Scale(kNewTabSize) + Scale(kSidePadding) + Scale(kCornerRadius);
173	    const int available = rcClient.Width() - left - reserved;
174	    const int width = available / GetTabCount();
175	    return max(Scale(kTabMinWidth), min(width, Scale(kTabMaxWidth)));
176	}
177	
178	CRect CTabBar::TabRect(int index) const
179	{
180	    CRect rcClient;
181	    GetClientRect(&rcClient);
182	    const int width = TabWidth();
183	    const int left = Scale(kSidePadding) + Scale(kCornerRadius) + index * width;
184	    return CRect(left, Scale(kTabTop), left + width, rcClient.bottom);
185	}
186	
187	CRect CTabBar::CloseRect(int index) const
188	{
189	    const CRect tab = TabRect(index);
190	    const int size = Scale(kCloseSize);
191	    const int right = tab.right - Scale(kCloseMargin);
192	    const int top = tab.top + (tab.Height() - size) / 2;
193	    return CRect(right - size, top, right, top + size);
194	}
195	
196	CRect CTabBar::NewTabRect() const
197	{
198	    const int size = Scale(kNewTabSize);
199	    const int left = TabRect(GetTabCount()).left + Scale(kNewTabGap);
200	    const CRect tabArea = TabRect(0);
201	    const int top = tabArea.top + (tabArea.Height() - size) / 2;
202	    return CRect(left, top, left + size, top + size);
203	}
204	
205	CTabBar::HitResult CTabBar::HitTest(CPoint point) const
206	{
207	    HitResult hit;
208	    if (NewTabRect().PtInRect(point))
209	    {
210	        hit.newTab = true;
211	        return hit;
212	    }
213	    for (int i = 0; i < GetTabCount(); ++i)
214	    {
215	        if (TabRect(i).PtInRect(point))
216	        {
217	            hit.tab = i;
218	            const bool closeVisible = (i == m_active) || TabWidth() >= Scale(kCloseMinTabWidth);
219	            hit.close = closeVisible && CloseRect(i).PtInRect(point);
220	            return hit;
221	        }
222	    }
223	    return hit;
224	}
