45	    }
46	
47	    /** @brief 위쪽은 둥글고 아래쪽은 바깥으로 휘어 바닥과 이어지는 크롬 탭 모양 */
48	    void AddTabShape(GraphicsPath& path, const CRect& rc, int radius)
49	    {
50	        const REAL r = static_cast<REAL>(radius);
51	        const REAL l = static_cast<REAL>(rc.left), t = static_cast<REAL>(rc.top);
52	        const REAL rt = static_cast<REAL>(rc.right), b = static_cast<REAL>(rc.bottom);
53	        path.StartFigure();
54	        path.AddArc(l - 2 * r, b - 2 * r, 2 * r, 2 * r, 90.0f, -90.0f);   // 왼쪽 아래 바깥 곡선
55	        path.AddArc(l, t, 2 * r, 2 * r, 180.0f, 90.0f);                   // 왼쪽 위
56	        path.AddArc(rt - 2 * r, t, 2 * r, 2 * r, 270.0f, 90.0f);          // 오른쪽 위
57	        path.AddArc(rt, b - 2 * r, 2 * r, 2 * r, 180.0f, -90.0f);         // 오른쪽 아래 바깥 곡선
58	        path.CloseFigure();
59	    }
60	
61	    void DrawCross(Graphics& g, const CRect& rc, REAL penWidth)
62	    {
63	        Pen pen(kGlyphColor, penWidth);
64	        const REAL inset = rc.Width() * 0.3f;
65	        const REAL l = rc.left + inset, t = rc.top + inset;
66	        const REAL r = rc.right - inset, b = rc.bottom - inset;
67	        g.DrawLine(&pen, PointF(l, t), PointF(r, b));
68	        g.DrawLine(&pen, PointF(r, t), PointF(l, b));
69	    }
70	}
