241	void CTabBar::OnPaint()
242	{
243	    CPaintDC dc(this);
244	    CRect rcClient;
245	    GetClientRect(&rcClient);
246	
247	    CDC memDC;
248	    memDC.CreateCompatibleDC(&dc);
249	    CBitmap buffer;
250	    buffer.CreateCompatibleBitmap(&dc, rcClient.Width(), rcClient.Height());
251	    CBitmap* oldBitmap = memDC.SelectObject(&buffer);
252	
253	    const COLORREF background = ::GetSysColor(COLOR_3DFACE);
254	    memDC.FillSolidRect(rcClient, background);
255	
256	    {
257	        Graphics g(memDC.GetSafeHdc());
258	        g.SetSmoothingMode(SmoothingModeAntiAlias);
259	
260	        // 마우스가 올라간 선택 안 된 탭: 옅게 칠함
261	        if (m_hover.tab >= 0 && m_hover.tab != m_active)
262	        {
263	            GraphicsPath path;
264	            AddTabShape(path, TabRect(m_hover.tab), Scale(kCornerRadius));
265	            SolidBrush brush(ToColor(Mix(background, m_activeColor, 45)));
266	            g.FillPath(&brush, &path);
267	        }
268	
269	        // 탭 사이 구분선: 선택되거나 마우스가 올라간 탭 옆에는 그리지 않음 (크롬과 같음)
270	        Pen separator(ToColor(kSeparatorColor), 1.0f);
271	        for (int i = 1; i < GetTabCount(); ++i)
272	        {
273	            const bool hidden = (i == m_active || i - 1 == m_active || i == m_hover.tab || i - 1 == m_hover.tab);
274	            if (!hidden)
275	            {
276	                const CRect rc = TabRect(i);
277	                const REAL x = rc.left - 0.5f;
278	                g.DrawLine(&separator, PointF(x, static_cast<REAL>(rc.top + Scale(8))),
279	                           PointF(x, static_cast<REAL>(rc.bottom - Scale(6))));
280	            }
281	        }
282	
283	        // 선택된 탭: 아래 캔버스 영역과 같은 색으로 이어지게 칠함
284	        if (m_active >= 0)
285	        {
286	            GraphicsPath path;
287	            AddTabShape(path, TabRect(m_active), Scale(kCornerRadius));
288	            SolidBrush brush(ToColor(m_activeColor));
289	            g.FillPath(&brush, &path);
290	        }
291	
292	        g.Flush(FlushIntentionSync); // 아래 GDI 글자 그리기 전에 반영
293	
294	        for (int i = 0; i < GetTabCount(); ++i)
295	        {
296	            DrawTab(g, memDC, i);
297	        }
298	
299	        // + 단추
300	        const CRect rcNew = NewTabRect();
301	        if (m_hover.newTab)
302	        {
303	            SolidBrush hoverBrush(kButtonHoverColor);
304	            g.FillEllipse(&hoverBrush, static_cast<REAL>(rcNew.left), static_cast<REAL>(rcNew.top),
305	                          static_cast<REAL>(rcNew.Width()), static_cast<REAL>(rcNew.Height()));
306	        }
307	        Pen plusPen(kGlyphColor, static_cast<REAL>(Scale(2)) * 0.8f);
308	        const REAL cx = rcNew.left + rcNew.Width() / 2.0f;
309	        const REAL cy = rcNew.top + rcNew.Height() / 2.0f;
310	        const REAL arm = rcNew.Width() * 0.22f;
311	        g.DrawLine(&plusPen, PointF(cx - arm, cy), PointF(cx + arm, cy));
312	        g.DrawLine(&plusPen, PointF(cx, cy - arm), PointF(cx, cy + arm));
313	    }
314	
315	    dc.BitBlt(0, 0, rcClient.Width(), rcClient.Height(), &memDC, 0, 0, SRCCOPY);
316	    memDC.SelectObject(oldBitmap);
317	}
318	
319	void CTabBar::DrawTab(Graphics& g, CDC& dc, int index) const
320	{
321	    const Tab& tab = m_tabs[index];
322	    const CRect rcTab = TabRect(index);
323	    const CRect rcClose = CloseRect(index);
324	    const bool active = (index == m_active);
325	    const bool hovered = (index == m_hover.tab);
326	    const bool closeAllowed = active || TabWidth() >= Scale(kCloseMinTabWidth);
327	
328	    // × 자리에 표시할 것: 마우스가 올라가 있으면 ×, 아니면 저장 안 된 변경 표시 ●, 선택된 탭은 ×
329	    enum class Glyph { None, Close, Modified } glyph = Glyph::None;
330	    if (hovered && closeAllowed)
331	    {
332	        glyph = Glyph::Close;
333	    }
334	    else if (tab.modified)
335	    {
336	        glyph = Glyph::Modified;
337	    }
338	    else if (active)
339	    {
340	        glyph = Glyph::Close;
341	    }
342	
343	    // 제목
344	    CRect rcText(rcTab.left + Scale(kTextPadding), rcTab.top, rcClose.left - Scale(4), rcTab.bottom);
345	    if (glyph == Glyph::None && !closeAllowed)
346	    {
347	        rcText.right = rcTab.right - Scale(kCloseMargin);
348	    }
349	    CFont* oldFont = (m_hFont != nullptr) ? dc.SelectObject(CFont::FromHandle(m_hFont)) : nullptr;
350	    dc.SetBkMode(TRANSPARENT);
351	    dc.SetTextColor(active ? kActiveTextColor : kInactiveTextColor);
352	    dc.DrawText(tab.title, &rcText, DT_SINGLELINE | DT_VCENTER | DT_END_ELLIPSIS | DT_NOPREFIX);
353	    if (oldFont != nullptr)
354	    {
355	        dc.SelectObject(oldFont);
356	    }
357	
358	    if (glyph == Glyph::Close)
359	    {
360	        if (m_hover.tab == index && m_hover.close)
361	        {
362	            SolidBrush hoverBrush(kButtonHoverColor);
363	            g.FillEllipse(&hoverBrush, static_cast<REAL>(rcClose.left), static_cast<REAL>(rcClose.top),
364	                          static_cast<REAL>(rcClose.Width()), static_cast<REAL>(rcClose.Height()));
365	        }
366	        DrawCross(g, rcClose, static_cast<REAL>(Scale(2)) * 0.7f);
367	    }
368	    else if (glyph == Glyph::Modified)
369	    {
370	        SolidBrush dot(kGlyphColor);
371	        const REAL d = static_cast<REAL>(Scale(8));
372	        g.FillEllipse(&dot, rcClose.left + (rcClose.Width() - d) / 2, rcClose.top + (rcClose.Height() - d) / 2, d, d);
373	    }
374	}
