using System;
using System.Collections.Generic;
using System.Drawing;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;

public static class W
{
    [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr h, int m, IntPtr w, IntPtr l);
    [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SendMessageW")] public static extern IntPtr SendMessageStr(IntPtr h, int m, IntPtr w, string l);
    [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "SendMessageW")] public static extern IntPtr SendMessageSb(IntPtr h, int m, IntPtr w, StringBuilder l);
    [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr h, int m, IntPtr w, IntPtr l);
    [DllImport("user32.dll")] public static extern IntPtr GetDlgItem(IntPtr h, int id);
    [DllImport("user32.dll")] public static extern int GetDlgCtrlID(IntPtr h);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetClassName(IntPtr h, StringBuilder s, int n);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
    public delegate bool EnumProc(IntPtr h, IntPtr l);
    [DllImport("user32.dll")] public static extern bool EnumChildWindows(IntPtr h, EnumProc p, IntPtr l);
    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc p, IntPtr l);
    [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
    [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
    [DllImport("user32.dll")] public static extern bool IsWindow(IntPtr h);
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
    [DllImport("user32.dll")] public static extern bool GetClientRect(IntPtr h, out RECT r);
    [DllImport("user32.dll")] public static extern bool ClientToScreen(IntPtr h, ref POINT p);
    [DllImport("user32.dll")] public static extern IntPtr GetParent(IntPtr h);
    [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr h, IntPtr after, int x, int y, int cx, int cy, uint flags);
    [DllImport("user32.dll")] public static extern bool SetCursorPos(int x, int y);
    [DllImport("user32.dll")] public static extern bool GetCursorPos(out POINT p);
    [DllImport("user32.dll")] public static extern uint GetDpiForWindow(IntPtr h);
    [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
    [DllImport("user32.dll")] public static extern bool AttachThreadInput(uint a, uint b, bool attach);
    [DllImport("kernel32.dll")] public static extern uint GetCurrentThreadId();
    [DllImport("user32.dll")] public static extern void keybd_event(byte vk, byte scan, uint flags, UIntPtr extra);
    [StructLayout(LayoutKind.Sequential)] public struct RECT { public int L, T, R, B; }
    [StructLayout(LayoutKind.Sequential)] public struct POINT { public int X, Y; }

    public const int WM_SETTEXT = 0x000C, WM_GETTEXT = 0x000D, WM_CLOSE = 0x0010, BM_CLICK = 0x00F5;
    public const int WM_MOUSEMOVE = 0x0200, WM_LBUTTONDOWN = 0x0201, WM_LBUTTONUP = 0x0202, MK_LBUTTON = 1;

    public static string Text(IntPtr h) { var sb = new StringBuilder(4096); GetWindowText(h, sb, sb.Capacity); return sb.ToString(); }
    public static string MsgText(IntPtr h) { var sb = new StringBuilder(8192); SendMessageSb(h, WM_GETTEXT, (IntPtr)sb.Capacity, sb); return sb.ToString(); }
    public static string Cls(IntPtr h) { var sb = new StringBuilder(256); GetClassName(h, sb, sb.Capacity); return sb.ToString(); }
    public static IntPtr LParam(int x, int y) { return (IntPtr)((y << 16) | (x & 0xFFFF)); }

    public static List<IntPtr> TopWindows(uint pid)
    {
        var list = new List<IntPtr>();
        EnumWindows((h, l) => { uint p; GetWindowThreadProcessId(h, out p); if (p == pid && IsWindowVisible(h)) list.Add(h); return true; }, IntPtr.Zero);
        return list;
    }

    public static List<IntPtr> Children(IntPtr parent)
    {
        var list = new List<IntPtr>();
        EnumChildWindows(parent, (h, l) => { list.Add(h); return true; }, IntPtr.Zero);
        return list;
    }

    /// <summary>Visible dialog (#32770) of the process other than the main window, waiting up to ms.</summary>
    public static IntPtr WaitDialog(uint pid, IntPtr main, int ms)
    {
        var end = DateTime.Now.AddMilliseconds(ms);
        do
        {
            foreach (var h in TopWindows(pid))
                if (h != main && Cls(h) == "#32770") return h;
            Thread.Sleep(100);
        } while (DateTime.Now < end);
        return IntPtr.Zero;
    }

    public static bool WaitGone(IntPtr h, int ms)
    {
        var end = DateTime.Now.AddMilliseconds(ms);
        while (DateTime.Now < end) { if (!IsWindow(h) || !IsWindowVisible(h)) return true; Thread.Sleep(100); }
        return false;
    }

    public static bool WaitTitle(IntPtr h, string title, int ms)
    {
        var end = DateTime.Now.AddMilliseconds(ms);
        do { if (Text(h) == title) return true; Thread.Sleep(100); } while (DateTime.Now < end);
        return false;
    }

    public static void Click(IntPtr dlg, int id) { PostMessage(GetDlgItem(dlg, id), BM_CLICK, IntPtr.Zero, IntPtr.Zero); }

    public static void Topmost(IntPtr h, bool on)
    {
        SetWindowPos(h, on ? (IntPtr)(-1) : (IntPtr)(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0010);
    }

    public static Bitmap CaptureRect(int x, int y, int w, int h)
    {
        var bmp = new Bitmap(w, h);
        using (var g = Graphics.FromImage(bmp)) g.CopyFromScreen(x, y, 0, 0, bmp.Size);
        return bmp;
    }

    public static Bitmap Capture(IntPtr h)
    {
        RECT r; GetWindowRect(h, out r);
        return CaptureRect(r.L, r.T, r.R - r.L, r.B - r.T);
    }

    /// <summary>File name edit box of a common item (open/save) dialog.</summary>
    public static IntPtr FileNameEdit(IntPtr dlg)
    {
        foreach (var h in Children(dlg))
        {
            if (Cls(h) != "Edit") continue;
            int id = GetDlgCtrlID(h);
            IntPtr p = GetParent(h);
            int pid = GetDlgCtrlID(p);
            int gpid = GetDlgCtrlID(GetParent(p));
            if (id == 1001 || id == 1148 || pid == 1148 || gpid == 1148) return h;
        }
        return IntPtr.Zero;
    }

    public static string Dump(IntPtr dlg)
    {
        var sb = new StringBuilder();
        foreach (var h in Children(dlg))
            sb.AppendFormat("{0} id={1} parentId={2} vis={3} '{4}'\n", Cls(h), GetDlgCtrlID(h), GetDlgCtrlID(GetParent(h)), IsWindowVisible(h), Text(h));
        return sb.ToString();
    }

    /// <summary>Text of the message box's static text (id 0xFFFF).</summary>
    public static string MessageBoxText(IntPtr box)
    {
        foreach (var h in Children(box))
            if (Cls(h) == "Static" && GetDlgCtrlID(h) == 0xFFFF) return MsgText(h);
        return "";
    }

    public static bool BringToFront(IntPtr h)
    {
        if (GetForegroundWindow() == h) return true;
        SetForegroundWindow(h);
        if (GetForegroundWindow() == h) return true;
        uint dummy;
        uint fgThread = GetWindowThreadProcessId(GetForegroundWindow(), out dummy);
        uint me = GetCurrentThreadId();
        if (fgThread != 0 && fgThread != me)
        {
            AttachThreadInput(me, fgThread, true);
            SetForegroundWindow(h);
            AttachThreadInput(me, fgThread, false);
        }
        Thread.Sleep(200);
        return GetForegroundWindow() == h;
    }

    /// <summary>{pixels equal to (r,g,b), pixels that are neither that nor white}</summary>
    public static int[] CountPixels(string path, int r, int g, int b)
    {
        using (var bmp = new Bitmap(path))
        {
            int match = 0, other = 0;
            for (int y = 0; y < bmp.Height; y++)
                for (int x = 0; x < bmp.Width; x++)
                {
                    var c = bmp.GetPixel(x, y);
                    if (c.R == r && c.G == g && c.B == b) match++;
                    else if (!(c.R == 255 && c.G == 255 && c.B == 255)) other++;
                }
            return new[] { match, other };
        }
    }

    /// <summary>Ctrl+key, only if h is still the foreground window.</summary>
    public static bool CtrlKey(IntPtr h, byte vk)
    {
        if (GetForegroundWindow() != h) return false;
        keybd_event(0x11, 0, 0, UIntPtr.Zero);
        keybd_event(vk, 0, 0, UIntPtr.Zero);
        keybd_event(vk, 0, 2, UIntPtr.Zero);
        keybd_event(0x11, 0, 2, UIntPtr.Zero);
        return true;
    }
}

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

