184	    /// <summary>Text of a status bar part in another process (SB_GETTEXTW into memory allocated there).</summary>
185	    public static string StatusText(IntPtr bar, int part, uint pid)
186	    {
187	        IntPtr proc = OpenProcess(0x0008 | 0x0010 | 0x0020, false, pid);
188	        if (proc == IntPtr.Zero) return "<OpenProcess failed " + Marshal.GetLastWin32Error() + ">";
189	        try
190	        {
191	            IntPtr mem = VirtualAllocEx(proc, IntPtr.Zero, (UIntPtr)8192, 0x3000, 0x04);
192	            if (mem == IntPtr.Zero) return "<VirtualAllocEx failed " + Marshal.GetLastWin32Error() + ">";
193	            try
194	            {
195	                SendMessage(bar, 0x040D, (IntPtr)part, mem); // SB_GETTEXTW
196	                var buf = new byte[8192];
197	                UIntPtr read;
198	                if (!ReadProcessMemory(proc, mem, buf, (UIntPtr)buf.Length, out read)) return "<ReadProcessMemory failed>";
199	                string s = Encoding.Unicode.GetString(buf);
200	                int z = s.IndexOf('\0');
201	                return z >= 0 ? s.Substring(0, z) : s;
202	            }
203	            finally { VirtualFreeEx(proc, mem, UIntPtr.Zero, 0x8000); }
204	        }
205	        finally { CloseHandle(proc); }
206	    }
