/// <summary>Raw RT_ACCELERATOR entries of an exe: {flags (FVIRTKEY 1, NOINVERT 2, FSHIFT 4, FCONTROL 8, FALT 16), key, command}.</summary>
public static List<int[]> AccelTable(string exe, int id)
{
    var list = new List<int[]>();
    IntPtr mod = LoadLibraryEx(exe, IntPtr.Zero, 0x22); // LOAD_LIBRARY_AS_DATAFILE | LOAD_LIBRARY_AS_IMAGE_RESOURCE
    if (mod == IntPtr.Zero) return list;
    try
    {
        IntPtr res = FindResource(mod, (IntPtr)id, (IntPtr)9);
        if (res == IntPtr.Zero) return list;
        uint size = SizeofResource(mod, res);
        IntPtr p = LockResource(LoadResource(mod, res));
        for (int off = 0; off + 8 <= size; off += 8)
        {
            int flags = Marshal.ReadInt16(p, off) & 0xFFFF;
            list.Add(new[] { flags & 0x7F, Marshal.ReadInt16(p, off + 2) & 0xFFFF, Marshal.ReadInt16(p, off + 4) & 0xFFFF });
            if ((flags & 0x80) != 0) break;
        }
    }
    finally { FreeLibrary(mod); }
    return list;
}

