param([string]$Exe = 'E:\MyPaint_CandidatePackage_djlee\x64\Release\MyPaint.exe')
# Ghost tracing shortcuts: accelerator table, command routing, and real key presses when MyPaint has focus.
# ASCII only: PowerShell 5.1 reads BOM-less scripts in the ANSI code page. Korean texts come from ghost-expected.txt.
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [Text.Encoding]::UTF8
$scratch = Split-Path -Parent $MyInvocation.MyCommand.Path
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies System.Drawing -Path (Join-Path $scratch 'W.cs')
[W]::SetProcessDPIAware() | Out-Null

$expect = @{}
Get-Content -Encoding UTF8 (Join-Path $scratch 'ghost-expected.txt') | ForEach-Object { $k, $v = $_.Split('=', 2); $expect[$k] = $v }

$IDC_GHOST_TOGGLE = 1021; $IDC_GHOST_PIN = 1022; $IDC_STATUS = 1015
$ID_GHOST_TOGGLE = 32778; $ID_GHOST_PIN = 32779; $WM_COMMAND = 0x0111
$VK_G = 0x47; $VK_T = 0x54

$script:fails = 0
function Check($name, $ok, $detail) {
    if (-not $ok) { $script:fails++ }
    Write-Host ("[{0}] {1} :: {2}" -f $(if ($ok) { 'PASS' } else { 'FAIL' }), $name, $detail)
}
function Status() { [W]::StatusText([W]::GetDlgItem($main, $IDC_STATUS), 2, $pid_) }
function State() { "toggle=$([W]::GetCheck($main, $IDC_GHOST_TOGGLE)) pin=$([W]::GetCheck($main, $IDC_GHOST_PIN)) title='$([W]::Text($main))' status='$(Status)'" }
function Expect($name, $toggle, $pin, $status) {
    $t = [W]::GetCheck($main, $IDC_GHOST_TOGGLE); $p = [W]::GetCheck($main, $IDC_GHOST_PIN); $s = Status
    Check $name ($t -eq $toggle -and $p -eq $pin -and $s -eq $status) (State)
}

# 1. Accelerator table in the built exe
$acc = [W]::AccelTable($Exe, 129)
$toggle = $acc | Where-Object { $_[2] -eq $ID_GHOST_TOGGLE }
$pin = $acc | Where-Object { $_[2] -eq $ID_GHOST_PIN }
Check 'Ctrl+G accelerator' ($toggle -ne $null -and $toggle[1] -eq $VK_G -and ($toggle[0] -band 0x1D) -eq 0x09) ("entries=$($acc.Count) flags=$($toggle[0]) key=$($toggle[1])")
Check 'Ctrl+Shift+G accelerator' ($pin -ne $null -and $pin[1] -eq $VK_G -and ($pin[0] -band 0x1D) -eq 0x0D) ("flags=$($pin[0]) key=$($pin[1])")

$p = Start-Process $Exe -PassThru
$main = [IntPtr]::Zero
for ($i = 0; $i -lt 50 -and $main -eq [IntPtr]::Zero; $i++) { Start-Sleep -Milliseconds 100; $p.Refresh(); $main = $p.MainWindowHandle }
$pid_ = [uint32]$p.Id
Start-Sleep -Milliseconds 500
try {
    # 2. Real key presses, each sent only while MyPaint is still the foreground window
    $steps = @(
        @{ name = 'Ctrl+G: ghost on, no left tab'; shift = $false; vk = $VK_G; toggle = 1; pin = 0; status = $expect.noleft },
        @{ name = 'Ctrl+Shift+G: pin this tab (it is the source, no overlay)'; shift = $true; vk = $VK_G; toggle = 1; pin = 1; status = $expect.self },
        @{ name = 'Ctrl+T: new tab traces the pinned tab'; shift = $false; vk = $VK_T; toggle = 1; pin = 0; status = $expect.pinned1 },
        @{ name = 'Ctrl+Shift+G: pin moves to tab 2'; shift = $true; vk = $VK_G; toggle = 1; pin = 1; status = $expect.self },
        @{ name = 'Ctrl+Shift+G: unpin, back to the left tab'; shift = $true; vk = $VK_G; toggle = 1; pin = 0; status = $expect.left1 },
        @{ name = 'Ctrl+G: ghost off'; shift = $false; vk = $VK_G; toggle = 0; pin = 0; status = '' }
    )
    $keyboard = [W]::BringToFront($main)
    foreach ($s in $steps) {
        if (-not $keyboard) { Write-Host "[SKIP] $($s.name) :: MyPaint is not the foreground window"; continue }
        $sent = if ($s.shift) { [W]::CtrlShiftKey($main, $s.vk) } else { [W]::CtrlKey($main, $s.vk) }
        if (-not $sent) { $keyboard = $false; Write-Host "[SKIP] $($s.name) :: focus moved away"; continue }
        Start-Sleep -Milliseconds 500
        Expect $s.name $s.toggle $s.pin $s.status
    }

    # 3. The same commands posted directly (what the accelerators send)
    Write-Host "before posted commands: $(State)"
    $t0 = [W]::GetCheck($main, $IDC_GHOST_TOGGLE)
    [W]::PostMessage($main, $WM_COMMAND, [IntPtr]$ID_GHOST_TOGGLE, [IntPtr]::Zero) | Out-Null; Start-Sleep -Milliseconds 400
    Check 'ID_GHOST_TOGGLE flips the toggle' ([W]::GetCheck($main, $IDC_GHOST_TOGGLE) -eq 1 - $t0) (State)
    $p0 = [W]::GetCheck($main, $IDC_GHOST_PIN)
    [W]::PostMessage($main, $WM_COMMAND, [IntPtr]$ID_GHOST_PIN, [IntPtr]::Zero) | Out-Null; Start-Sleep -Milliseconds 400
    Check 'ID_GHOST_PIN flips the pin' ([W]::GetCheck($main, $IDC_GHOST_PIN) -eq 1 - $p0) (State)
}
finally {
    Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue
    Write-Host "failures: $script:fails"
}

