# Lists the tools registered in MyPaint's tooltip control (TTM_ENUMTOOLSW into memory allocated in that process).
# ASCII only: PowerShell 5.1 reads BOM-less scripts in the ANSI code page.
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [Text.Encoding]::UTF8
$scratch = Split-Path -Parent $MyInvocation.MyCommand.Path
Add-Type -AssemblyName System.Drawing
