[DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h, int cmd);

/// <summary>Text of a status bar part in another process (SB_GETTEXTW into memory allocated there).</summary>
public static string StatusText(IntPtr bar, int part, uint pid)
{
    IntPtr proc = OpenProcess(0x0008 | 0x0010 | 0x0020, false, pid);
    if (proc == IntPtr.Zero) return "<OpenProcess failed " + Marshal.GetLastWin32Error() + ">";
    try
    {
        IntPtr mem = VirtualAllocEx(proc, IntPtr.Zero, (UIntPtr)8192, 0x3000, 0x04);
        if (mem == IntPtr.Zero) return "<VirtualAllocEx failed " + Marshal.GetLastWin32Error() + ">";
        try
        {
            SendMessage(bar, 0x040D, (IntPtr)part, mem); // SB_GETTEXTW
            var buf = new byte[8192];
            UIntPtr read;
            if (!ReadProcessMemory(proc, mem, buf, (UIntPtr)buf.Length, out read)) return "<ReadProcessMemory failed>";
            string s = Encoding.Unicode.GetString(buf);
            int z = s.IndexOf('\0');
            return z >= 0 ? s.Substring(0, z) : s;
        }
        finally { VirtualFreeEx(proc, mem, UIntPtr.Zero, 0x8000); }
    }
    finally { CloseHandle(proc); }
}

