using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class TT
{
    [DllImport("kernel32.dll", SetLastError = true)] static extern IntPtr OpenProcess(uint access, bool inherit, uint pid);
    [DllImport("kernel32.dll", SetLastError = true)] static extern IntPtr VirtualAllocEx(IntPtr p, IntPtr addr, UIntPtr size, uint type, uint protect);
    [DllImport("kernel32.dll", SetLastError = true)] static extern bool VirtualFreeEx(IntPtr p, IntPtr addr, UIntPtr size, uint type);
    [DllImport("kernel32.dll", SetLastError = true)] static extern bool ReadProcessMemory(IntPtr p, IntPtr addr, byte[] buf, UIntPtr size, out UIntPtr n);
    [DllImport("kernel32.dll", SetLastError = true)] static extern bool WriteProcessMemory(IntPtr p, IntPtr addr, byte[] buf, UIntPtr size, out UIntPtr n);
    [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
    [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr h, int m, IntPtr w, IntPtr l);
    [DllImport("user32.dll")] static extern int GetDlgCtrlID(IntPtr h);
    public delegate bool EnumProc(IntPtr h, IntPtr l);
    [DllImport("user32.dll")] static extern bool EnumWindows(EnumProc p, IntPtr l);
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetClassName(IntPtr h, StringBuilder s, int n);

    public static List<string> Tools(uint pid)
    {
        var result = new List<string>();
        var tips = new List<IntPtr>();
        EnumWindows((h, l) => {
            uint p; GetWindowThreadProcessId(h, out p);
            var sb = new StringBuilder(64); GetClassName(h, sb, 64);
            if (p == pid && sb.ToString() == "tooltips_class32") tips.Add(h);
            return true; }, IntPtr.Zero);
        IntPtr proc = OpenProcess(0x0008 | 0x0010 | 0x0020, false, pid);
        IntPtr mem = VirtualAllocEx(proc, IntPtr.Zero, (UIntPtr)16384, 0x3000, 0x04);
        try
        {
            foreach (IntPtr tip in tips)
            {
                int count = SendMessage(tip, 0x0400 + 13, IntPtr.Zero, IntPtr.Zero).ToInt32(); // TTM_GETTOOLCOUNT
                result.Add(string.Format("tooltip {0}: {1} tools", tip, count));
                for (int i = 0; i < count; i++)
                {
                    var ti = new byte[72];                       // TTTOOLINFOW on x64
                    BitConverter.GetBytes(72).CopyTo(ti, 0);     // cbSize
                    BitConverter.GetBytes((long)mem + 256).CopyTo(ti, 48); // lpszText -> buffer after the struct
                    UIntPtr n;
                    WriteProcessMemory(proc, mem, ti, (UIntPtr)ti.Length, out n);
                    WriteProcessMemory(proc, mem + 256, new byte[2], (UIntPtr)2, out n);
                    SendMessage(tip, 0x0400 + 58, (IntPtr)i, mem); // TTM_ENUMTOOLSW
                    var back = new byte[16384];
                    ReadProcessMemory(proc, mem, back, (UIntPtr)back.Length, out n);
                    uint flags = BitConverter.ToUInt32(back, 4);
                    long uId = BitConverter.ToInt64(back, 16);
                    int id = (flags & 1) != 0 ? GetDlgCtrlID((IntPtr)uId) : -1; // TTF_IDISHWND
                    string text = Encoding.Unicode.GetString(back, 256, back.Length - 256);
                    int z = text.IndexOf('\0'); if (z >= 0) text = text.Substring(0, z);
                    result.Add(string.Format("  #{0} flags=0x{1:X} ctrlId={2} text='{3}'", i, flags, id, text));
                }
            }
        }
        finally { VirtualFreeEx(proc, mem, UIntPtr.Zero, 0x8000); CloseHandle(proc); }
        return result;
    }
}
